// ============================================================
// TREE_NODES — V6 12-family taxonomy with depth-2 sub-genres.
// Hierarchical: each node has parent (or null at root).
// ============================================================

const TREE_NODES = [
  { id: 'droneModal', name: 'Drone and modal ornament', parent: null, description: 'Music built on a sustained tonal foundation with modal melodic organization and elaborate ornament. Where the music sits in pitch space rather than where it sits geographically.' },
  { id: 'functionalSong', name: 'Functional song-form', parent: null, description: 'Verse-chorus-bridge architecture organized by functional chord progressions. The largest sonic territory in recorded popular music globally.' },
  { id: 'improvOnFrame', name: 'Improvisation on a frame', parent: null, description: 'Live elaboration over a fixed harmonic, modal, or metric frame. Jazz lineages, raga gat, dastgah, choro, gypsy jazz, free improvisation.' },
  { id: 'distortedRock', name: 'Amplified rock and metal', parent: null, description: 'Electric guitar through distortion as the primary tonal voice. Rock, metal, punk, hardcore, shoegaze, post-rock and their kin.' },
  { id: 'mcRhythm', name: 'Rhythmic verse over beats', parent: null, description: 'Rapped, chanted, or toasted verse over back-line beats. Hip hop, drill, trap, grime, dancehall MCing, reggaeton, kwaito, naija drill.' },
  { id: 'groovePercussion', name: 'Percussion-led dance', parent: null, description: 'Percussion-forward syncopated dance traditions. African, Afro-diasporic, Latin American grooves where the back-line IS the music.' },
  { id: 'artMusic', name: 'Through-composed art music', parent: null, description: 'Codified theoretical systems, concert-listening function, often notated or formally transmitted. Western classical, Hindustani and Carnatic, gagaku, gamelan repertoire, Persian dastgah, Andalusi, Chinese classical.' },
  { id: 'balladPoetry', name: 'Ballad and song-poetry', parent: null, description: 'Voice with minimal accompaniment, lyric and poetic priority, intimate scale. Singer-songwriter, fado, chanson, bardic song, troubadour descendants, narrative ballad traditions.' },
  { id: 'ritualDevotional', name: 'Sacred and devotional', parent: null, description: 'Music-as-worship — congregational, ecstatic, contemplative, or trance-inducing. Gospel, qawwali, kirtan, Sufi sama, Sacred Harp, gregorian, Buddhist liturgy, candomblé, Pentecostal services.' },
  { id: 'bassSystem', name: 'Bass-soundsystem', parent: null, description: 'Bass treated as architecture rather than back-line. Reggae, dub, dancehall, dubstep, jungle, UK garage, grime, sound-system traditions.' },
  { id: 'electronicDance', name: 'Cyclical electronic dance', parent: null, description: 'Programmed cyclical beats designed for the dance floor. House, techno, trance, hardstyle, footwork, gqom, amapiano, baile funk, batida, kuduro.' },
  { id: 'experimentalElec', name: 'Experimental electronic', parent: null, description: 'Headphone-oriented production-driven electronic music. IDM, ambient, drone, glitch, vaporwave, synthwave, lo-fi, industrial, noise, hyperpop, musique concrète.' },
  { id: 'droneModal.vocal', name: 'Drone-vocal traditions', parent: 'droneModal', description: 'Single voice or unison vocal carried over a sustained tonal foundation, with melodic content built from microtonal ornament rather than chord changes. Throat-singing overtone traditions, raga-vocal khayal and dhrupad, qawwali, sean-nós, Sardinian a tenores, Tuvan and Mongolian xöömei.' },
  { id: 'droneModal.string', name: 'Drone-string traditions', parent: 'droneModal', description: 'Plucked, bowed, or struck strings that carry melody and drone simultaneously, often via sympathetic resonance or open-tuning scordatura. Sitar, sarod, tanpura, oud, saz, gusli, kantele, hardanger fiddle, Hawaiian slack-key, Appalachian dulcimer.' },
  { id: 'droneModal.modalElectric', name: 'Modal electric strings', parent: 'droneModal', description: 'Electric guitar (and bass) treated as a modal/drone instrument rather than a functional-harmony tool: power-chord drones, single-tonic centers, harmonic stasis instead of progression. Krautrock, drone-doom, post-rock, raga-rock, modal-jazz electric.' },
  { id: 'droneModal.overtone', name: 'Overtone and throat singing', parent: 'droneModal', description: 'Manipulation of harmonic overtones as melodic content; single vocalists producing multiple simultaneous tones.' },
  { id: 'droneModal.windPipe', name: 'Drone winds and pipes', parent: 'droneModal', description: 'Wind-driven instruments built around a fixed drone tone over which melody is played: Highland and uilleann pipes, Galician gaita, Bulgarian gaida, didgeridoo, mizmar/zurna paired with drone-pipes, mey, Scottish piobaireachd. The drone is the harmonic foundation; melody fits around it.' },
  { id: 'droneModal.appalachian', name: 'Appalachian and old-time mountain', parent: 'droneModal', description: 'Drone-fiddle, banjo, and ballad traditions of the Southern American mountains. Modal organization, scordatura tunings, oral transmission.' },
  { id: 'functionalSong.country', name: 'Country', parent: 'functionalSong', description: 'American country lineages: I-IV-V harmonic backbone, narrative-first lyric subjects, vocal ornament traditions descended from blue-yodel and Anglo-Celtic balladry, and an instrumentation signature centered on fiddle, steel guitar, and acoustic-or-electric guitars. Born from the 1927 Bristol sessions and continually reinvented since.' },
  { id: 'functionalSong.country.preCommercial', name: 'Pre-commercial roots', parent: 'functionalSong.country', description: 'Pre-1940s country roots: hillbilly, cowboy songs, stringband and 1920s-30s commercial-recording-era recordings, blue-yodel and Western swing precursors. Acoustic instrumentation and oral-tradition repertoire transitioning to commercial recording.' },
  { id: 'functionalSong.country.honkyTonkEra', name: 'Honky-tonk era', parent: 'functionalSong.country', description: 'Postwar barroom country built on pedal steel, electric guitar, fiddle, and shuffle back-line; emotionally-direct heartbreak-and-drinking lyric subjects. Encompasses classic honky-tonk, the Bakersfield Sound, and truck-driving country.' },
  { id: 'functionalSong.country.nashville', name: 'Nashville Sound and Countrypolitan', parent: 'functionalSong.country', description: '1957-onward producer-led Nashville Sound and Countrypolitan: lush string-and-vocal-chorus arrangements smoothing country into adult-pop crossover; fiddle and steel deemphasized in favor of orchestral textures.' },
  { id: 'functionalSong.country.outlaw', name: 'Outlaw and progressive country', parent: 'functionalSong.country', description: 'Songwriter-driven country reaction against Nashville polish: rock-leaning back-lines, literary-quality lyric authorship, autobiographical and antiauthoritarian subject matter.' },
  { id: 'functionalSong.country.neoTrad', name: 'Neotraditional and Texas country', parent: 'functionalSong.country', description: '1980s revival of pre-Countrypolitan honky-tonk values: full pedal-steel-and-fiddle restoration, traditional-country songwriting templates returned to the radio mainstream. Encompasses Texas country and Red Dirt scenes.' },
  { id: 'functionalSong.country.contempMain', name: 'Contemporary mainstream country', parent: 'functionalSong.country', description: 'Post-2000 mainstream Nashville country fused with hip-hop, rock, and pop production templates: heavily-compressed back-lines, beat-driven arrangements, hooky chorus-emphasis song architecture.' },
  { id: 'functionalSong.country.americana', name: 'Americana and alt-country', parent: 'functionalSong.country', description: 'Insurgent-country and alt-country lineage: country songcraft processed through indie-rock production sensibilities, gothic-and-literary lyric register, deliberate refusal of mainstream-Nashville polish.' },
  { id: 'functionalSong.country.countryRock', name: 'Country rock', parent: 'functionalSong.country', description: 'Late-1960s through 1970s amplified-country and rock fusion subgenre; pedal-steel-and-acoustic-guitar foreground over rock-rhythm-section foundation, close-harmony-vocal arrangement, country-songwriting-sensibility applied to rock-album format. Gram Parsons, The Eagles, Poco, The Flying Burrito Brothers, Linda Ronstadt as reference points.' },
  { id: 'functionalSong.country.westernSwing', name: 'Western swing', parent: 'functionalSong.country', description: '1930s-1950s Texas-and-Oklahoma dance-band tradition fusing string-band fiddle-and-steel-guitar instrumentation with swing-era jazz harmony and arrangement; Bob Wills and his Texas Playboys as reference.' },
  { id: 'functionalSong.soulRb.doowop', name: 'Doo-wop', parent: 'functionalSong.soulRb', description: '1950s-early-1960s African-American vocal-harmony group tradition; lead-and-backing-quartet-or-quintet vocal-foreground arrangement with light rhythm-section accompaniment, syllabic-nonsense-vocable harmony device foundational to soul and pop vocal-group lineage.' },
  { id: 'functionalSong.popRock.girlGroup', name: '1960s girl group', parent: 'functionalSong.popRock', description: 'Early-1960s teen-pop tradition centered on female-vocal-group lead-and-harmony arrangements over Brill-Building songwriting and Wall-of-Sound or Motown-era studio production; foundational to subsequent female-pop-vocal lineage.' },
  { id: 'functionalSong.popRock.synthpop', name: 'Synthpop', parent: 'functionalSong.popRock', description: 'Late-1970s through 1980s electronic-pop subgenre defined by foreground-synthesizer instrumentation, drum-machine percussion, vocoder-and-electronic-vocal treatment, and verse-chorus pop song-form; Depeche Mode, OMD, Pet Shop Boys, Erasure, Yazoo as reference.' },
  { id: 'functionalSong.popRock.newWave', name: 'New wave', parent: 'functionalSong.popRock', description: 'Late-1970s through mid-1980s post-punk-derived pop subgenre incorporating angular guitar texture, synthesizer accents, and short-song-form pop sensibility; Talking Heads, Blondie, The Cars, Elvis Costello, Devo, Squeeze as reference points.' },
  { id: 'functionalSong.popRock.folkRock', name: 'Folk rock', parent: 'functionalSong.popRock', description: 'Mid-1960s through 1970s American-and-British amplified folk subgenre fusing acoustic-folk songwriting tradition with electric-rock instrumentation; The Byrds, Bob Dylan electric era, Simon and Garfunkel, Crosby Stills Nash and Young, Fairport Convention as reference.' },
  { id: 'functionalSong.popRock.skiffle', name: 'Skiffle', parent: 'functionalSong.popRock', description: 'UK 1953-1958 working-class amateur DIY-folk-jazz hybrid genre using washboard, tea-chest bass, guitar, and harmonica; Lonnie Donegan as reference; foundational precursor to British Invasion (The Beatles, The Hollies, and most British 1960s beat bands began as skiffle groups).' },
  { id: 'functionalSong.popRock.yachtRock', name: 'Yacht rock', parent: 'functionalSong.popRock', description: 'Late-1970s through mid-1980s smooth-AOR pop-rock subgenre defined by jazz-and-R&B-derived chord vocabulary, polished West-Coast studio production, and adult-contemporary romance-and-introspection lyric content; Steely Dan, Doobie Brothers (post-McDonald era), Toto, Christopher Cross, Hall and Oates, Kenny Loggins, Boz Scaggs as reference.' },
  { id: 'functionalSong.soulRb', name: 'Soul, R&B and funk', parent: 'functionalSong', description: 'Gospel-derived secular Black American song organized around vocal-forward storytelling, I-IV-V-leaning harmony with extensive substitutions, and a tight rhythm-section interlock. Soul, funk, R&B, Northern soul / Motown, Southern soul, classic R&B, modern R&B, neo-soul. The continuous lineage from spiritual to streaming.' },
  { id: 'functionalSong.crooners', name: 'Tin Pan Alley and crooners', parent: 'functionalSong', description: 'Pre-rock American song tradition: Tin Pan Alley, Brill Building, Great American Songbook, doo-wop, vocal-jazz pop. AABA-form sentimental songwriting, foregrounded vocal interpretation, jazz-derived chord vocabulary.' },
  { id: 'functionalSong.popRock', name: 'Pop and pop-rock', parent: 'functionalSong', description: 'Anglosphere mainstream pop and pop-rock: verse-chorus song architecture, hook-driven melodic writing, guitar-and-back-line instrumentation rooted in 1960s British-and-California melodic-rock template. Encompasses soft rock, indie pop, dream pop, and alternative pop.' },
  { id: 'functionalSong.bluesElectric', name: 'Electric blues song', parent: 'functionalSong', description: 'Postwar electrified blues organized as I-IV-V (and I-IV-V-IV) song forms with shuffle, two-step, or backbeat rhythm. Chicago, Memphis, Texas, jump blues. Built around the electric guitar as primary voice, harmonica as second voice, and a rhythm section anchoring the twelve-bar form.' },
  { id: 'functionalSong.bluesAcoustic', name: 'Acoustic blues song', parent: 'functionalSong', description: 'Pre-electric blues song-forms: Piedmont fingerpicking, country blues with chord movement, jug-band, hokum. Acoustic-guitar-led ensemble structures distinct from the holler-and-narrative idiom under balladPoetry.bluesNarrative.' },
  { id: 'functionalSong.mexican', name: 'Mexican song forms', parent: 'functionalSong', description: 'Mexican song forms: ranchera, mariachi-songbook, banda, norteño, sierreño, corrido, bolero mexicano. Accordion-and-bajo-sexto or string-and-trumpet ensembles; courtly, narrative, and romantic lyric subjects.' },
  { id: 'functionalSong.brazilianSong', name: 'Brazilian song', parent: 'functionalSong', description: 'Brazilian song architecture: extended-harmony chord vocabulary descended from samba and choro, sophisticated melodic-and-harmonic interplay. Ranges from intimate bossa nova through MPB to mass-popular sertanejo.' },
  { id: 'functionalSong.tropicalSong', name: 'Caribbean and tropical song', parent: 'functionalSong', description: 'Caribbean-Atlantic song forms: bachata, son-derived song, tropical bolero, kompa song-form, kizomba song-form. Romantic-narrative lyric mode over Latin-percussion-led back-lines.' },
  { id: 'functionalSong.tejanoBorder', name: 'Tex-Mex and borderlands', parent: 'functionalSong', description: 'Mexican-American borderlands song: conjunto, tejano, mariachi-American. Accordion-and-bajo-sexto core instrumentation modernized through country-and-rock production; bilingual-or-Spanish lyric tradition.' },
  { id: 'functionalSong.tejanoBorder.ranchera', name: 'Ranchera', parent: 'functionalSong.tejanoBorder', description: 'Mexican folk-popular song-form from rural-ranch (rancho) tradition; waltz-3/4 or bolero-2/4 meters, emotional-expressive vocal-delivery foreground, lyric content centered on lost-love-and-homeland themes, performed by mariachi-ensemble or solo-with-guitar; foundational to Mexican-popular-music identity, distinct from mariachi-ensemble proper (which is the instrumentation) by song-form-and-vocal foreground. José Alfredo Jiménez, Pedro Infante, Vicente Fernández, Chavela Vargas, Lola Beltrán as reference.' },
  { id: 'functionalSong.tejanoBorder.corrido', name: 'Corrido', parent: 'functionalSong.tejanoBorder', description: 'Mexican narrative-ballad song-form documenting historical events, folk-heroes, revolutionary battles, border-life narrative content; 6/8 or 4/4 meter, eight-line stanza-form with assonant rhyme, accompanied by guitar-and-accordion-and-bajo-sexto small-ensemble; tradition dating to 19th-century Mexican-Revolution era with Pancho Villa, Emiliano Zapata, and revolutionary-hero subject matter; modern narcocorrido sub-tradition extends the narrative form into drug-trade documentation.' },
  { id: 'functionalSong.eastAsianPop', name: 'East Asian pop', parent: 'functionalSong', description: 'East Asian mainstream pop: J-pop, K-pop, Mandopop, Cantopop, V-pop. Producer-team songwriting, idol-group performance format, genre-collage track architecture, polished synth-and-vocal production.' },
  { id: 'functionalSong.eastAsianPop.enka', name: 'Enka', parent: 'functionalSong.eastAsianPop', description: 'Postwar Japanese sentimental-ballad tradition; melismatic kobushi-ornamented vocal style over Western-instrumentation-with-shamisen-and-koto-coloration accompaniment, lyric content centered on yearning, lost love, and homeland-nostalgia themes, foundational to mid-20th-century Japanese popular vocal practice.' },
  { id: 'functionalSong.southAsianPop', name: 'South Asian pop', parent: 'functionalSong', description: 'South Asian mainstream pop: filmi (Bollywood and regional film music), Punjabi pop, Tamil pop, Indian-diaspora crossover. Harmonium-and-tabla heritage modernized through synthesizer arrangements; dance-floor crossover orientation.' },
  { id: 'functionalSong.europop', name: 'Continental European pop', parent: 'functionalSong', description: 'Continental European mainstream pop: chanson-pop, schlager, Italian cantautore-pop, Greek pop, Russian estrada, Polish pop, Eurovision pop. Region-specific lyrical and harmonic conventions over imported Anglosphere production templates.' },
  { id: 'functionalSong.africanPop', name: 'African popular song', parent: 'functionalSong', description: 'Sub-Saharan-African mainstream pop song-forms: afrobeats (Naija), hiplife song, makossa-pop, Ghanaian and Nigerian-radio song. Highlife guitar lineage modernized through programmed back-lines and trap-derived production.' },
  { id: 'functionalSong.africanPop.congoleseRumba', name: 'Congolese rumba', parent: 'functionalSong.africanPop', description: 'Mid-1940s through 1960s Congolese-Kinshasa-and-Brazzaville urban dance music; Cuban-rumba-influenced electric-guitar-foreground arrangement (the mi-solo / sebene clean-guitar interplay), call-and-response vocal practice, foundational lineage to Afro-Cuban-influenced African pop and to soukous.' },
  { id: 'functionalSong.africanPop.isicathamiya', name: 'Isicathamiya / mbube', parent: 'functionalSong.africanPop', description: 'Zulu South African a-cappella male-vocal-group tradition emerging from 1920s mining-hostel weekend competitions; tightly-choreographed close-harmony eight-to-fifteen-voice ensemble with bass-led vocal foundation, lineage extending from Solomon Linda 1939 Mbube origin through Ladysmith Black Mambazo international codification.' },
  { id: 'functionalSong.midEastNAfricanPop', name: 'Middle Eastern and North African pop', parent: 'functionalSong', description: 'Middle-Eastern and North-African mainstream pop: Arab pop, Egyptian pop, Persian pop, Turkish pop, Israeli mainstream. Maqam-melodic-vocabulary preserved over imported Western production; vocal melisma as cultural signifier.' },
  { id: 'functionalSong.iberian', name: 'Iberian song', parent: 'functionalSong', description: 'Iberian-language mainstream song: fado (Lisbon and Coimbra), Portuguese pop, Spanish copla and canción, Catalan cançó, Galician and Basque songwriter traditions. Lyric-forward romantic-and-saudade affect.' },
  { id: 'improvOnFrame.americanJazz', name: 'American jazz lineages', parent: 'improvOnFrame', description: 'The American jazz lineage from New Orleans through avant-garde and fusion: improvised-soloing-over-chord-changes architecture, swing-derived rhythmic feel, instrumental virtuosity as central value. All sub-styles trace to early-20th-century Black-American synthesis of West-African rhythmic logic with European harmonic tools.' },
  { id: 'improvOnFrame.americanJazz.early', name: 'Early jazz', parent: 'improvOnFrame.americanJazz', description: 'Pre-bebop jazz: New Orleans, Dixieland, hot jazz, Chicago and Kansas City jazz, swing-era jazz-orchestra ensemble. Collective-improvisation polyphonic texture and dance-band function predominant.' },
  { id: 'improvOnFrame.americanJazz.preJazzRagtime', name: 'Pre-jazz ragtime', parent: 'improvOnFrame.americanJazz', description: 'Composed-piano-and-ensemble syncopated dance music tradition (1890s-1910s peak), foundational to early jazz and stride-piano lineage; multi-strain march form, Sousa-influenced harmonic structure crossed with African-American syncopation, primarily piano solo with brass-band and fingerstyle-guitar transcriptional parallels.' },
  { id: 'improvOnFrame.americanJazz.stridePiano', name: 'Stride piano', parent: 'improvOnFrame.americanJazz', description: '1920s-1940s Harlem virtuoso solo-piano tradition; ragtime-derived left-hand walking-tenths-and-ten-and-octave-leap stride pattern under improvised right-hand melodic-and-chord-melody work, foundation for swing and bebop pianism.' },
  { id: 'improvOnFrame.americanJazz.boogieWoogie', name: 'Boogie-woogie', parent: 'improvOnFrame.americanJazz', description: '1920s-1940s African-American piano-blues idiom; ostinato-eight-to-the-bar left-hand-bass figures (rolling-bass, walking-bass, broken-octave-bass patterns) under blues-frame right-hand improvisation, bridge between rural blues and urban early-R&B piano.' },
  { id: 'improvOnFrame.americanJazz.latinJazz', name: 'Latin jazz', parent: 'improvOnFrame.americanJazz', description: '1940s-onward jazz subgenre fusing bebop and post-bop jazz vocabulary with Afro-Cuban-and-Brazilian rhythmic foundation; cubop, mambo-jazz, samba-jazz, and broader pan-Latin-American jazz hybrid lineage.' },
  { id: 'improvOnFrame.americanJazz.bop', name: 'Bop and modal', parent: 'improvOnFrame.americanJazz', description: 'Bebop and its immediate descendants: hard bop, post-bop, modal jazz, cool jazz. Tight-combo virtuoso soloing on chord changes at fast tempos, harmonic-vocabulary expansion through extended chords and substitutions, listening-music orientation rather than dance.' },
  { id: 'improvOnFrame.americanJazz.kansasCity', name: 'Kansas City swing', parent: 'improvOnFrame.americanJazz', description: '1930s-1940s African-American Kansas City regional swing-era jazz subgenre fusing big-band swing with twelve-bar-blues frame and riff-based head arrangements; Count Basie Orchestra, Bennie Moten, Andy Kirk, Jay McShann territorial bands as reference; distinguished from contemporaneous New York-and-Chicago swing by blues-frame foreground and riff-foreground arrangement.' },
  { id: 'improvOnFrame.americanJazz.hardBop', name: 'Hard bop', parent: 'improvOnFrame.americanJazz', description: '1953-1965 jazz subgenre extending bebop with blues-and-gospel-derived melodic vocabulary and rhythmic-groove emphasis; Art Blakey and the Jazz Messengers, Horace Silver, Cannonball Adderley, Lee Morgan, Hank Mobley early-Blue-Note era as reference.' },
  { id: 'improvOnFrame.americanJazz.avant', name: 'Avant-garde jazz', parent: 'improvOnFrame.americanJazz', description: 'Free jazz and post-bop avant-garde: free-form soloing without fixed chord changes, spiritual-jazz expansiveness, ECM-school chamber aesthetic, AACM-derived improvisation traditions.' },
  { id: 'improvOnFrame.americanJazz.fusion', name: 'Jazz fusion', parent: 'improvOnFrame.americanJazz', description: 'Jazz crossed with rock, funk, electronic, or world-music vocabularies: electrified instrumentation, groove-based rather than swing-based back-line, extended-form composition.' },
  { id: 'improvOnFrame.americanJazz.smoothVocal', name: 'Vocal jazz and smooth jazz', parent: 'improvOnFrame.americanJazz', description: 'Vocal jazz tradition: Great-American-Songbook-era crooners through modern crooner revival, plus smooth-jazz instrumental sub-style. Melodic-interpretation-over-improvisation emphasis, conversational vocal delivery.' },
  { id: 'improvOnFrame.americanJazz.soulJazz', name: 'Soul jazz', parent: 'improvOnFrame.americanJazz', description: 'Mid-1950s through 1970s organ-trio-and-quartet jazz subgenre fusing hard-bop jazz vocabulary with R&B-and-gospel sensibility; Hammond-B3-tonewheel-organ foreground with Leslie-speaker rotary-modulation, electric-guitar-and-drums supporting trio, occasional saxophone-or-trumpet horn voice; blues-and-gospel-derived melodic vocabulary applied to jazz harmonic frame.' },
  { id: 'improvOnFrame.stringImprov', name: 'String virtuoso improvisation', parent: 'improvOnFrame', description: 'String-led improvisation traditions: gypsy jazz, Brazilian choro, klezmer instrumental, jam-grass and progressive bluegrass. Acoustic-string-ensemble improvisation over fixed chordal frames, virtuoso unison-and-trade-eights tradition.' },
  { id: 'improvOnFrame.bluegrass', name: 'Bluegrass and string-band improvisation', parent: 'improvOnFrame', description: 'Five-piece interlocking acoustic ensemble (guitar, mandolin, banjo, fiddle, upright bass) with composed-vocal song forms and improvised solo breaks. Pioneered postwar in Appalachian-stringband lineage, codified into a virtuosic chamber-folk tradition with strict instrumentation conventions and high-tempo expectations.' },
  { id: 'improvOnFrame.latinJazz', name: 'Latin and Afro-diasporic jazz', parent: 'improvOnFrame', description: 'Latin-American improvised idioms over jazz harmonic tools: Afro-Cuban jazz, samba-jazz, bossa-jazz, Ethio-jazz. Latin-percussion-led back-lines under jazz solo improvisation.' },
  { id: 'improvOnFrame.indianClassicalImprov', name: 'South Asian classical improvisation', parent: 'improvOnFrame', description: 'Codified Indian classical improvisation: Hindustani gat-toda and alap-jor-jhala, Carnatic ragam-tanam-pallavi. Raga-and-tala framework with extensive melodic-and-tempo elaboration.' },
  { id: 'improvOnFrame.persianArabImprov', name: 'Persian and Arab classical improvisation', parent: 'improvOnFrame', description: 'Middle-Eastern improvisation traditions: Persian dastgah, Arab taqsim, Turkish makam improvisation, mawwāl-instrumental. Modal-melodic improvisation within fixed maqam-frame, microtonal pitch vocabulary.' },
  { id: 'improvOnFrame.celticTraditional', name: 'Celtic traditional improvisation', parent: 'improvOnFrame', description: 'Celtic-Atlantic improvised session traditions: Irish session music, Scottish fiddle traditions, Cape Breton style. Tune-medley structure with embellishment-and-variation as the improvisational locus.' },
  { id: 'improvOnFrame.klezmerImprov', name: 'Klezmer and Eastern European improvisation', parent: 'improvOnFrame', description: 'Ashkenazi Jewish dance and ceremonial music with extensive ornament (krekhtsen, kneytshn, dreydlekh) and improvisation over modal-tetrachord frames (freygish, mishebeyrekh). Clarinet, violin, accordion, brass, percussion. Wedding repertoire, Hasidic niggun, and modern revival/concert traditions.' },
  { id: 'improvOnFrame.jamFree', name: 'Jam-band and free improvisation', parent: 'improvOnFrame', description: 'Long-form improvised rock and free improvisation: jam-band tradition, free-improv ensembles, electroacoustic improvisation. Process-and-listening orientation, structureless-or-loosely-structured collective improvisation.' },
  { id: 'distortedRock.classic', name: 'Classic and foundational rock', parent: 'distortedRock', description: 'Foundational distorted-rock lineage: garage rock, psychedelic rock, hard rock, blues-rock, southern rock, rock-and-roll. Single-coil-and-humbucker tones through tube amplification, blues-derived melodic vocabulary, drums-bass-guitar power-trio core.' },
  { id: 'distortedRock.surfRock', name: 'Surf rock', parent: 'distortedRock', description: 'Early-1960s Southern California instrumental-rock subgenre defined by spring-reverb-saturated electric-guitar foreground (Fender Reverb tank tone), fast-picked single-note melodic figures, tremolo-arm vibrato, and minor-pentatonic-and-modal Eastern-Mediterranean-derived melodic vocabulary; iconic guitar-driven instrumental dance music.' },
  { id: 'distortedRock.lateAnalogMajor', name: 'Late-analog major rock', parent: 'distortedRock', description: 'American major-label rock production tradition spanning 1985-2000: SSL-and-Neve console infrastructure, multi-room flagship-studio tracking, plate-reverb-and-digital-delay spatial signature, late-analog tape mastering with first-generation Pro Tools editing. Encompasses arena-rock, hair-metal, AOR, and heartland-rock subtraditions sharing this production-aesthetic-and-infrastructure period regardless of harmonic-or-lyrical idiom.' },
  { id: 'distortedRock.metal', name: 'Metal', parent: 'distortedRock', description: 'High-gain metal lineage: down-tuned-and-detuned guitar architecture, double-bass-pedal back-line, growled-shrieked-or-soaring vocal traditions. Sub-genres span temporal speeds from drone-doom (sub-30bpm) to grindcore (>240bpm) with shared distortion-saturated tonal palette.' },
  { id: 'distortedRock.punk', name: 'Punk and hardcore', parent: 'distortedRock', description: 'Punk and its descendants: punk proper, hardcore, post-hardcore, post-punk, dance-punk, art-punk, emo. Aggressive tempo, simplified-or-deliberately-amateurish technique, anti-virtuoso aesthetic, ideologically-committed lyric stance.' },
  { id: 'distortedRock.popPunk', name: 'Pop-punk', parent: 'distortedRock', description: 'Mid-1970s through 1990s-onward punk subgenre fusing punk\'s amateur-aesthetic and tempo with pop melody and verse-chorus song-form; Ramones originator, Buzzcocks early UK extension, 1990s Green Day Dookie 1994 and Blink-182 mainstream-radio crossover, contemporary pop-punk revival lineage.' },
  { id: 'distortedRock.emo', name: 'Emo', parent: 'distortedRock', description: 'Mid-1980s through present-day post-hardcore-derived rock subgenre defined by emotionally-confessional lyric content, dynamic-quiet-loud-quiet song architecture, and clean-guitar-arpeggio-and-distorted-power-chord textural alternation; Rites of Spring 1985 originator, 1990s second-wave through Sunny Day Real Estate, Cap\'n Jazz, Mineral, American Football, 2000s third-wave mainstream through Jimmy Eat World, Dashboard Confessional, My Chemical Romance, Fall Out Boy.' },
  { id: 'distortedRock.southernRock', name: 'Southern rock', parent: 'distortedRock', description: 'Late-1960s through 1970s American Southern blues-rock subgenre featuring twin-or-triple-lead-guitar arrangements, pedal-steel cross-pollination from country, blues-rock harmonic-melodic foundation, and Southern-Appalachian regional cultural identity. The Allman Brothers Band, Lynyrd Skynyrd, ZZ Top, The Marshall Tucker Band, The Charlie Daniels Band, Molly Hatchet as reference.' },
  { id: 'distortedRock.noiseRock', name: 'Noise rock', parent: 'distortedRock', description: 'Late-1970s through 1990s experimental-rock subgenre foregrounding dissonance, feedback, prepared-guitar techniques, and noise-as-melodic-element; Sonic Youth Daydream Nation 1988, Swans Cop 1984, Big Black Atomizer 1986, The Jesus Lizard, Helmet, Unsane as reference.' },
  { id: 'distortedRock.alternative', name: 'Alternative and indie rock', parent: 'distortedRock', description: 'Distorted rock outside metal-and-punk taxonomies: alt-rock, indie rock, dream pop, shoegaze, slowcore, math rock, jangle pop, grunge. Sonic-texture experimentation, melodic songwriting, post-punk-derived production sensibilities.' },
  { id: 'distortedRock.experimental', name: 'Experimental rock', parent: 'distortedRock', description: 'Experimental-leaning distorted rock: krautrock, no-wave, art-rock, post-rock, drone rock, noise rock. Deliberate refusal of pop song-architecture, long-form composition, texture-and-process emphasis.' },
  { id: 'distortedRock.progressiveRock', name: 'Progressive rock', parent: 'distortedRock', description: 'Late-1960s through 1970s rock subgenre incorporating classical-and-jazz harmonic vocabulary, extended instrumental composition, suite-and-concept-album form, and virtuosic instrumental performance; Yes, Genesis, King Crimson, Pink Floyd, Rush, Jethro Tull as reference points.' },
  { id: 'distortedRock.gothicRock', name: 'Gothic rock', parent: 'distortedRock', description: 'Late-1970s through 1980s post-punk-derived rock subgenre defined by atmospheric chorused-clean-guitar texture, prominent bass-guitar foreground, deep-baritone vocal delivery, melancholic-and-occult lyric content, and dark theatrical aesthetic.' },
  { id: 'distortedRock.artRock', name: 'Art rock', parent: 'distortedRock', description: 'Late-1960s through 1980s art-school-and-avant-garde-influenced rock subgenre prioritizing aesthetic-conceptual-experimentation over virtuosic-instrumental-performance; Roxy Music, David Bowie Berlin trilogy, Brian Eno, Talking Heads experimental period, Peter Gabriel solo era as reference points.' },
  { id: 'distortedRock.glamRock', name: 'Glam rock', parent: 'distortedRock', description: 'Early-to-mid-1970s British-and-American rock subgenre defined by androgynous-theatrical performance aesthetic, glitter-platform stage costuming, anthemic mid-tempo riff-rock musical foundation, and pop-foregrounded songwriting; David Bowie Ziggy era, T.Rex, Slade, Sweet, New York Dolls as reference; distinct from later 1980s hair-metal commercial-glam derivative.' },
  { id: 'distortedRock.regional', name: 'Regional rock variants', parent: 'distortedRock', description: 'Non-Anglosphere rock scenes that import the distorted-rock vocabulary into regional musical-and-linguistic contexts: Latin alternative, J-rock, K-rock, Indo-rock, anadolu rock, Russian rock, Italian rock. Local-language vocals, regional melodic-modal influences, parallel scene infrastructure.' },
  { id: 'mcRhythm.usHipHop', name: 'US hip hop', parent: 'mcRhythm', description: 'American hip-hop lineage: rapped vocal performance over sampled-or-programmed back-lines, regional production-aesthetic divergence. Evolves from 1970s Bronx block-party origins through East-Coast boom-bap, West-Coast G-funk, Southern trap, and Midwest battle-rap to current radio-pop dominance.' },
  { id: 'mcRhythm.usHipHop.eastCoast', name: 'East Coast', parent: 'mcRhythm.usHipHop', description: 'New York and east-coast hip-hop lineage: boom-bap golden-era production, sampled-jazz-and-soul backings, lyrical-virtuoso emphasis, plus the recent NYC-and-Brooklyn drill scenes.' },
  { id: 'mcRhythm.usHipHop.westCoast', name: 'West Coast', parent: 'mcRhythm.usHipHop', description: 'California and west-coast hip-hop lineage: G-funk heavy-funk-derived production, gangsta-narrative lyric mode, hyphy and west-coast-trap successor scenes.' },
  { id: 'mcRhythm.usHipHop.southern', name: 'Southern', parent: 'mcRhythm.usHipHop', description: 'Southern-US hip-hop production traditions: Atlanta trap, Memphis horror-rap, Houston chopped-and-screwed, dirty-south, crunk. 808-sub-bass back-line foundation, snap-and-clap percussion, melodic-pitched vocal performance.' },
  { id: 'mcRhythm.usHipHop.modern', name: 'Modern hip hop', parent: 'mcRhythm.usHipHop', description: 'Late-2010s and 2020s mainstream-American hip-hop: drill, cloud rap, melodic rap, plugg, rage rap, trap soul. Pitched-vocal melodic performance, hyperpop-adjacent production aesthetics, internet-distributed authorship.' },
  { id: 'mcRhythm.usHipHop.gangsta', name: 'Gangsta rap', parent: 'mcRhythm.usHipHop', description: 'Mid-1980s through 1990s American hip-hop subgenre foregrounding street-narrative, drug-and-crime lyric content, and confrontational-and-political performance stance; Ice-T, NWA, Ice Cube, Dr. Dre, Snoop Dogg, Tupac, Mobb Deep, Eazy-E as reference; West-Coast-LA and East-Coast-NYC strands. Cross-cuts geographic east/west categorization through stylistic-content rubric.' },
  { id: 'mcRhythm.usHipHop.consciousRap', name: 'Conscious hip-hop', parent: 'mcRhythm.usHipHop', description: 'Late-1980s through present-day American hip-hop subgenre foregrounding politically-and-socially-engaged lyric content, jazz-and-soul-sample-based production, and intricate-rhyme-craft performance practice; Public Enemy, A Tribe Called Quest, De La Soul, KRS-One, Mos Def, Talib Kweli, Common, The Roots, Kendrick Lamar as reference.' },
  { id: 'mcRhythm.intlHipHop', name: 'International hip hop', parent: 'mcRhythm', description: 'Hip-hop scenes outside the US: UK, French, German, Spanish, Russian, Japanese, Korean and other national scenes. Local-language vocal performance over imported-or-locally-produced back-lines; regionally-distinct production-and-lyric conventions.' },
  { id: 'mcRhythm.drill', name: 'Drill', parent: 'mcRhythm', description: 'Drill rap diaspora: Chicago origin, Brooklyn evolution, UK transmutation, continental crossover. Sliding-808 sub-bass and skipped-snare percussion as production signature, narrative-aggressive lyric mode.' },
  { id: 'mcRhythm.reggaeton', name: 'Reggaeton and Latin trap', parent: 'mcRhythm', description: 'Caribbean-Latino MC tradition: reggaeton, perreo, Latin trap, urbano latino. Dembow-derived back-line, Spanish-language vocal performance, dance-floor and erotic-narrative lyric subjects.' },
  { id: 'mcRhythm.afroDiasporic', name: 'African and diasporic MCing', parent: 'mcRhythm', description: 'African and Afro-diasporic MC traditions: kwaito, hiplife, Naija drill, gqom-MC, asakaa, Cape Town hip-hop. Regional-language vocal performance over Africa-developed electronic back-lines.' },
  { id: 'mcRhythm.experimental', name: 'Experimental hip hop', parent: 'mcRhythm', description: 'Experimental-leaning hip-hop: cloud rap, abstract hip-hop, industrial hip-hop, trap-experimental, hyperpop-rap fusion. Avant-aesthetic production, non-standard song architectures, internet-native distribution.' },
  { id: 'groovePercussion.westAfrican', name: 'West African popular', parent: 'groovePercussion', description: 'West-African popular-dance traditions: highlife, juju, fuji, hiplife, palm-wine, mbalax, makossa, bikutsi. Guitar-and-percussion ensemble architecture, Yoruba-and-Akan rhythmic foundations, cyclical-and-additive song-form.' },
  { id: 'groovePercussion.centralEastSouthAfrican', name: 'Central, East and Southern African', parent: 'groovePercussion', description: 'Central, East, and Southern African popular-dance lineage: soukous, ndombolo, taarab, benga, marrabenta, sungura, chimurenga, kwaito, mbira tradition. Interlocking-guitar-line architecture; regional-percussion specialization across the continent.' },
  { id: 'groovePercussion.cuban', name: 'Cuban-rooted', parent: 'groovePercussion', description: 'Cuban dance-music families: son-and-salsa lineage, Afro-Cuban rumba percussion-and-vocal, charanga-and-danza formal-court dance traditions. Clave-2:3-or-3:2 metric framework, layered conga-bongos-timbales percussion, montuno harmonic-vamp architecture.' },
  { id: 'groovePercussion.brazilian', name: 'Brazilian percussion-dance', parent: 'groovePercussion', description: 'Brazilian rhythmic-dance traditions: samba and its variants (partido alto, samba-enredo, samba de roda), axé, frevo, maracatu, baião, forró. Surdo-bass-beat-and-tamborim-percussion architecture; regional-rhythmic-pattern specialization.' },
  { id: 'groovePercussion.brazilian.pagode', name: 'Pagode', parent: 'groovePercussion.brazilian', description: 'Rio de Janeiro 1970s-onward urban-samba subgenre defined by samba-school small-group informal-roda performance practice; 2/4 meter with prominent tan-tan handheld drum-and-banjo-and-cavaquinho-and-pandeiro foreground; emergence through 1978 Cacique de Ramos roda samba scene with Bezerra da Silva, Fundo de Quintal, Almir Guineto establishing the idiom; 1990s commercial-pagode through Raça Negra, Os Travessos. Distinct from traditional samba by smaller ensemble-format and informal-roda performance context.' },
  { id: 'groovePercussion.latinAm', name: 'Other Latin American', parent: 'groovePercussion', description: 'Continental-Latin-American dance traditions: cumbia (Colombian and regional variants), bachata, merengue, vallenato, joropo, marinera, candombe, forró brasileiro. Accordion-and-percussion ensembles; regional-pattern-specific dance-floor functions.' },
  { id: 'groovePercussion.caribbean', name: 'Caribbean Afro-percussive', parent: 'groovePercussion', description: 'Non-Cuban Caribbean dance-music lineage: mento, calypso, soca, kaiso, parang, junkanoo, bomba, plena. Steel-drum and goombay-and-conga percussion-led ensembles; English-and-creole-language vocal tradition.' },
  { id: 'groovePercussion.afroDiasporicElec', name: 'Pan-African diasporic dance', parent: 'groovePercussion', description: 'Afro-diasporic electronic-dance descendants: afrobeat, kompa, kizomba, kuduro, semba, batida, coupé-décalé. Programmed-electronic back-lines fused with traditional African and Afro-Lusophone rhythmic foundations.' },
  { id: 'groovePercussion.funkPercussive', name: 'American funk', parent: 'groovePercussion', description: 'Funk lineage and its descendants: drum-on-the-one syncopation, psychedelic-funk variants, Afro-funk crossover (Nigerian afrobeat). Bass-and-drum interlock architecture, one-chord vamps as harmonic foundation.' },
  { id: 'groovePercussion.eastAsian', name: 'East Asian ensemble percussion', parent: 'groovePercussion', description: 'East-Asian large-ensemble percussion traditions: Japanese kumi-daiko (modern taiko), Korean samul nori, Chinese ceremonial-drum ensembles. Choreographed-physical-performance dimension, communal-village or temple origin reformatted into 20th-century concert presentation.' },
  { id: 'groovePercussion.eastAsian.samulNori', name: 'Samul nori', parent: 'groovePercussion.eastAsian', description: 'Korean four-instrument percussion tradition codified 1978 as concert-stage formalization of pungmul village-festival music; kkwaenggwari-jing-janggu-buk quartet, lead-and-response interlocking polyrhythmic structures derived from agricultural ceremonial drumming.' },
  { id: 'groovePercussion.americanMarching', name: 'American marching and drumline', parent: 'groovePercussion', description: 'American marching-band and drumline lineage: HBCU show-style, DCI drum corps, school marching bands, college pep bands. Outdoor-amplification-free dynamics, choreographed visual-element integration, syncopated-show-rhythm vocabulary distinct from European military-march tradition.' },
  { id: 'balladPoetry.indianBard', name: 'Indian/South Asian bardic and mystic-song', parent: 'balladPoetry', description: 'South-Asian poet-singer traditions: Bengali baul mystic-itinerants, Punjabi qawwali (also classed under devotional), Gujarati garba bardic, Sufi-and-bhakti devotional poet-singers. Voice-plus-drone-instrument architecture; oral-transmission of mystical or devotional poetry.' },
  { id: 'artMusic.westernEarly', name: 'Western early music', parent: 'artMusic', description: 'Pre-classical Western art music: medieval, renaissance, ars subtilior, Franco-Flemish school, baroque period, plus the 20th-century historically-informed-performance movement that revived these repertoires. Modal-and-emerging-tonal harmonic vocabularies; pre-equal-temperament tunings.' },
  { id: 'artMusic.westernCommonPractice', name: 'Western common-practice', parent: 'artMusic', description: 'Western tonal common-practice classical: Classical era, Romantic, late-Romantic. Functional-harmony architecture, sonata-form-and-symphonic-form composition, opera, chamber music, and song-cycle as genres.' },
  { id: 'artMusic.westernModern', name: '20th-century and contemporary Western', parent: 'artMusic', description: 'Post-1900 Western art music: post-tonal serial composition, minimalism, neoclassicism, contemporary classical, electroacoustic composition. Refusal-or-extension of common-practice tonality; expanded timbral palette.' },
  { id: 'artMusic.southAsian', name: 'South Asian classical', parent: 'artMusic', description: 'Hindustani and Carnatic codified traditions; the structural, compositional, theoretical apparatus around raga.' },
  { id: 'artMusic.eastAsian', name: 'East Asian art music', parent: 'artMusic', description: 'East Asian classical traditions: Japanese gagaku and shōmyō, Korean gugak and sanjo, Chinese jingju and kunqu opera, guqin and pipa solo traditions, jiangnan sizhu chamber music. Pentatonic-and-heptatonic modal frameworks; court-and-temple performance contexts.' },
  { id: 'artMusic.eastAsian.beijingOpera', name: 'Beijing opera (jingju)', parent: 'artMusic.eastAsian', description: 'Chinese classical theatrical music tradition codified late-18th-century Qing-dynasty Qianlong court; stylized vocal-aria foreground over jinghu-erhu-yueqin-pipa melodic ensemble and luogu percussion ensemble, four role-types (sheng / dan / jing / chou) each with distinct vocal-and-gestural vocabularies.' },
  { id: 'artMusic.eastAsian.cantoneseOpera', name: 'Cantonese opera (yueju)', parent: 'artMusic.eastAsian', description: 'Cantonese classical theatrical music tradition centered on Pearl-River-Delta and Hong Kong communities; melismatic Cantonese-language aria over yueqin-erhu-and-luogu accompaniment, three-and-four-character role-type system parallel to but distinct from Beijing opera.' },
  { id: 'artMusic.middleEasternClassical', name: 'Middle Eastern art music', parent: 'artMusic', description: 'Middle Eastern and North African codified-classical traditions: Persian dastgah, Arab tarab and maqam, Andalusi nuba, Turkish makam classical, Azeri mughām. Microtonal modal frameworks, melismatic-vocal-and-instrumental elaboration, semi-improvised performance practice.' },
  { id: 'artMusic.southeastAsian', name: 'Southeast Asian art music', parent: 'artMusic', description: 'Southeast Asian art-music traditions: Javanese gamelan repertoire, Balinese gamelan, Sundanese gamelan, Cambodian pinpeat, Thai mahori, Burmese hsaing waing, Vietnamese ca trù. Tuned-percussion-ensemble architecture; layered ostinato-and-variation compositional logic.' },
  { id: 'artMusic.southeastAsian.thaiClassical', name: 'Thai classical', parent: 'artMusic.southeastAsian', description: 'Thai court-and-temple classical music tradition centered on piphat tuned-percussion-ensemble repertoire; ranat-ek-and-ranat-thum xylophones, khong-wong gong-circles, taphon-and-klong-thad drums, pi-nai oboe; heptatonic-equidistant tuning system; classical Mahori chamber-ensemble variant adds saw-three-string-fiddles and chakhe zither.' },
  { id: 'balladPoetry.angloSingerSong', name: 'Anglo singer-songwriter', parent: 'balladPoetry', description: 'Anglosphere solo songwriter tradition (American, British, Canadian): voice-and-acoustic-guitar (or piano) intimate format, lyric-as-primary-vehicle, confessional-or-narrative authorship. Spans 1960s folk-revival origins through contemporary indie folk and bedroom songwriting.' },
  { id: 'balladPoetry.chansonFado', name: 'Chanson and fado', parent: 'balladPoetry', description: 'Romance-language literary-songwriter traditions: French chanson, Portuguese fado (Lisbon and Coimbra), Italian cantautore, Greek éntechno. Text-as-foundation aesthetic, intimate accompaniment, melodramatic vocal interpretation.' },
  { id: 'balladPoetry.latinAmTroubadour', name: 'Latin American troubadour', parent: 'balladPoetry', description: 'Latin-American singer-poet tradition: cantautor, nueva canción, trova mexicana, nueva trova cubana, canto popular uruguayo, folklore argentino. Acoustic-guitar accompaniment, ideologically-committed and pastoral lyric authorship, oral-and-recorded transmission.' },
  { id: 'balladPoetry.latinAmTroubadour.milonga', name: 'Milonga', parent: 'balladPoetry.latinAmTroubadour', description: 'Argentine-and-Uruguayan rural-pampas song-and-dance form pre-dating-and-parallel-to tango; 2/4 syncopated meter, faster-tempo-than-tango, payada-troubadour-and-folklore-rural lyric tradition (rural-and-rural-folk content distinct from tango\'s urban-melancholic content), guitar-and-bandoneon-and-violin-and-voice instrumentation; tradition both gave rise to and developed parallel to urban-tango through the late 19th century, with Hilario Cuadros, Atahualpa Yupanqui, Mercedes Sosa as reference points within the broader folklore argentino lineage.' },
  { id: 'balladPoetry.slavicBard', name: 'Slavic and Russian bardic', parent: 'balladPoetry', description: 'Slavic-language poet-with-guitar tradition: Russian bard song (Soviet-era poet-with-guitar lineage), Polish poezja śpiewana, Czech-and-Slovak folk-poetic song, South-Slavic kantautor. Literary-quality lyric authorship, kitchen-and-campfire intimate performance contexts, samizdat-circulated tape transmission under Soviet bloc.' },
  { id: 'balladPoetry.celticBalladic', name: 'Celtic and British balladic', parent: 'balladPoetry', description: 'Celtic-Atlantic balladic traditions: Irish sean-nós unaccompanied vocal, Scottish balladry and bothy ballad, English broadside, Welsh hymn-balladry, Cape Breton Gaelic, Newfoundland outport. Narrative-song-as-primary-vehicle; often unaccompanied or with sparse accompaniment.' },
  { id: 'balladPoetry.medEastPoetic', name: 'Middle Eastern poetic vocal', parent: 'balladPoetry', description: 'Middle-Eastern poetic-vocal tradition: Urdu-and-Persian ghazal, Persian poetry-vocal, Sufi poetic singing, Arabic mawwāl. Highly-codified poetic forms set to maqam-derived melodic-modal vocabulary; semi-improvised vocal interpretation.' },
  { id: 'balladPoetry.bluesNarrative', name: 'Blues narrative ballad', parent: 'balladPoetry', description: 'African-American narrative-song tradition: Delta-blues poetic narrative, Piedmont fingerpicking, work songs, field hollers, prison songs, hokum-blues vaudeville. Lyric-as-primary-vehicle; blues-derived melodic-modal phrasing; oral-tradition repertoire transmission.' },
  { id: 'balladPoetry.mediterraneanBallad', name: 'Mediterranean balladic', parent: 'balladPoetry', description: 'Mediterranean balladic traditions: Greek rebetiko (urban-cabaret song), Sicilian-and-Neapolitan canzone, Sephardi Ladino song. Modal-and-microtonal melodic vocabulary, oud-bouzouki-or-guitar accompaniment, narrative-and-romantic lyric subjects.' },
  { id: 'balladPoetry.westAfricanGriot', name: 'West African griot praise-singing', parent: 'balladPoetry', description: 'West-African praise-singing oral tradition: Mandé jeli (Mandinka, Bambara, Khassonké), Wolof géwél, Fula gawlo, Wassoulou hunters-music. Heptatonic-and-pentatonic Mande tonal frame, kora-balafon-ngoni instrumental palette, hereditary specialist transmission, panegyric-and-historical narrative as primary lyric mode. Mali-Senegal-Guinea-Gambia-Mauritania-Burkina regional core.' },
  { id: 'ritualDevotional.christianGospel', name: 'Christian gospel and liturgical', parent: 'ritualDevotional', description: 'Christian liturgical-and-congregational sacred song: Black gospel, Sacred Harp shape-note, Anglican choral, Russian Orthodox, Coptic, Pentecostal worship, sacred steel, southern gospel. Worship-function performance contexts spanning ecstatic-Pentecostal through formal-cathedral aesthetics.' },
  { id: 'ritualDevotional.sufi', name: 'Sufi devotional', parent: 'ritualDevotional', description: 'Sufi devotional-music tradition: Indian-and-Pakistani qawwali, Mevlevi sama, Maghreb madih, Arab inshad, dhikr remembrance-ceremonies. Repetitive-melodic-cycle architecture intended to induce trance-like contemplative or ecstatic states.' },
  { id: 'ritualDevotional.hindu', name: 'Hindu devotional', parent: 'ritualDevotional', description: 'Hindu devotional and ceremonial music: kirtan, bhajan, abhang, dhrupad-bhakti, Tamil Saiva, ārtī, Vedic chant. Devotion-as-vehicle aesthetic; harmonium-and-tabla accompaniment; congregational call-and-response architecture common.' },
  { id: 'ritualDevotional.buddhist', name: 'Buddhist liturgical', parent: 'ritualDevotional', description: 'Buddhist liturgical chant: Japanese shōmyō, Tibetan multiphonic chant, throat-chanting, Theravada chant (Thai-Burmese-Sri Lankan), Chinese-and-Korean Pure Land liturgy. Melodic-modal monastic recitation; deep-fundamental-chest-resonance vocal techniques in some traditions.' },
  { id: 'ritualDevotional.jewish', name: 'Jewish liturgical', parent: 'ritualDevotional', description: 'Jewish liturgical-and-devotional song: Ashkenazi cantorial khazonus, Hasidic niggunim, Yemenite Torah cantillation, Sephardi sacred bakkashot, Ladino devotional. Hebrew-and-Aramaic text settings; regional-melodic-modal vocabularies; synagogue-and-domestic performance contexts.' },
  { id: 'ritualDevotional.islamic', name: 'Islamic recitation and devotional', parent: 'ritualDevotional', description: 'Islamic sacred recitation and devotional song: Qur\'anic tajwīd recitation, naʿat poetic praise-of-the-prophet, taraweeh prayer-cycles, the five-times-daily athān call to prayer. Maqam-derived melodic frameworks; voice-only-or-percussion-permitted instrumentation per legal-school interpretation.' },
  { id: 'ritualDevotional.afroDiasporic', name: 'Afro-diasporic ceremonial', parent: 'ritualDevotional', description: 'Afro-diasporic ceremonial sacred music: Brazilian candomblé, Cuban santería/Lukumí, Haitian vodou, Brazilian umbanda, Moroccan Gnawa. Yoruba-and-Bantu-derived percussion-and-vocal architecture; orisha-and-lwa worship as ceremonial function.' },
  { id: 'ritualDevotional.indigenous', name: 'Indigenous ceremonial', parent: 'ritualDevotional', description: 'Indigenous American and Australian-Aboriginal sacred-music traditions: Plains powwow song, Pueblo and Navajo ceremonial, Inuit drum-dance, ayahuasca-icaros (Amazonian shamanic), Mapuche ceremonial, Aboriginal songlines. Ceremony-bound performance contexts; voice-and-percussion architecture.' },
  { id: 'ritualDevotional.americanSacred', name: 'American sacred and oral', parent: 'ritualDevotional', description: 'Sacred song traditions of the Americas drawing on shape-note, work-song, and field-holler heritage: Sacred Harp, slave spirituals, prison-and-work-song spirituals. Communal-and-occupational performance contexts; oral-tradition transmission; shape-note literacy as preservation infrastructure.' },
  { id: 'bassSystem.jamaican', name: 'Jamaican lineage', parent: 'bassSystem', description: 'Jamaican sound-system music: ska, rocksteady, reggae roots, dub, dancehall, ragga, lovers\' rock, nyabinghi. Sub-bass-as-architecture; off-beat skanking guitar-and-keyboard; drop-and-skank rhythmic foundation.' },
  { id: 'bassSystem.ukSoundsystem', name: 'UK soundsystem', parent: 'bassSystem', description: 'UK-developed bass-music continuum: UK garage, 2-step, dubstep, grime, future garage, UK funky. Sub-bass-and-syncopated-back-line foundation; MC-and-vocal-sample tradition descended from Jamaican sound-system import.' },
  { id: 'bassSystem.bassDescendants', name: 'Bass-music descendants', parent: 'bassSystem', description: 'Bass-music descendants of UK soundsystem: drum-and-bass, jungle, neurofunk, riddim, breakbeat. 160-180bpm tempo range; chopped-Amen-break percussion-and-sub-bass architecture; festival-and-club-scene oriented.' },
  { id: 'bassSystem.dubDescendants', name: 'Dub descendants', parent: 'bassSystem', description: 'Dub aesthetic carried into adjacent electronic genres: dub techno, dub poetry, ambient dub, electro-dub, French dub. Effects-saturated-and-spaced-out production aesthetic; reverb-and-delay-as-instrument approach.' },
  { id: 'bassSystem.reggaeDiaspora', name: 'Reggae diaspora', parent: 'bassSystem', description: 'Non-Jamaican reggae traditions: UK reggae and lovers\' rock, French reggae, German reggae, African reggae, Brazilian reggae, reggae en español, 2-Tone ska revival. Local-language vocal performance over reggae-back-line architecture.' },
  { id: 'electronicDance.house', name: 'House and descendants', parent: 'electronicDance', description: 'House music sub-styles: Chicago house, deep house, garage house, microhouse, lo-fi house, italo house, Latin house, tech-house. Four-on-floor kick foundation; 120-130bpm tempo; soul-and-disco-derived vocal-and-melodic content.' },
  { id: 'electronicDance.techno', name: 'Techno', parent: 'electronicDance', description: 'Techno lineage: Detroit founding tradition, Berlin minimal-and-hard, peak-time, industrial techno. Four-on-floor kick at 125-150bpm; machine-like aesthetic; refusal of vocal-melodic content in favor of timbral-and-rhythmic exploration.' },
  { id: 'electronicDance.trance', name: 'Trance', parent: 'electronicDance', description: 'Trance lineage: uplifting, psychedelic, Goa, progressive, hard, vocal trance. 132-145bpm four-on-floor with melodic-emotional builds-and-drops architecture; supersaw-and-pad timbral signature.' },
  { id: 'electronicDance.hardstyle', name: 'Hardstyle and hardcore-techno', parent: 'electronicDance', description: 'Hard-and-fast electronic dance: gabber, hardstyle, frenchcore, raw hardstyle, terror, uptempo hardcore. Distorted-kick-as-lead architecture; 150-200+bpm tempo; screamed-or-pitched-up vocal samples.' },
  { id: 'electronicDance.continental', name: 'Continental electronic dance', parent: 'electronicDance', description: 'Continental-European dance-music traditions: German techno, French touch, Belgian dance, eurodance, italo-disco descendants. Region-specific production aesthetics fusing house-and-techno foundations with local-pop-melodic sensibilities.' },
  { id: 'electronicDance.africanDance', name: 'African electronic dance', parent: 'electronicDance', description: 'African-developed electronic dance: gqom, amapiano, kuduro, afrohouse, singeli. Region-specific tempo and rhythmic-cell signatures (gqom\'s 16th-note-triplet kick programming, amapiano\'s log-drum-and-deep-bass); African-language vocal samples.' },
  { id: 'electronicDance.latinElec', name: 'Latin electronic dance', parent: 'electronicDance', description: 'Latin-American electronic dance: baile funk, batida, dembow, perreo, electro-cumbia, RKT, guaracha. Latin-rhythmic-cell-as-foundation (dembow\'s boom-tic-tic-tic); Spanish-and-Portuguese vocal samples; club-scene oriented.' },
  { id: 'electronicDance.footwork', name: 'Footwork and juke', parent: 'electronicDance', description: 'Chicago-rooted accelerated dance music: footwork proper, juke, jersey club, ghettotech. 155-165bpm tempo; chopped-vocal-sample and triplet-kick percussion architecture; dance-battle performance context.' },
  { id: 'electronicDance.eurodance', name: 'Eurodance and hi-NRG', parent: 'electronicDance', description: '1990s and 2000s European commercial dance: hi-NRG, italo-disco, eurodance, eurobeat, freestyle. Songwriter-team production; rapping-male-and-singing-female vocal pair common; key-change drops over four-on-floor kick.' },
  { id: 'experimentalElec.ambient', name: 'Ambient and drone', parent: 'experimentalElec', description: 'Ambient and adjacent atmospheric-electronic genres: ambient proper, dark ambient, drone, deep ambient, ceremonial-ambient, isolationism. Beat-less or sub-beat texture-as-foundation; listening-context-as-environment aesthetic.' },
  { id: 'experimentalElec.idmGlitch', name: 'IDM and glitch', parent: 'experimentalElec', description: 'Intelligent-dance-music and glitch lineage: IDM, glitch, microsound, breakcore, mathstep, dariacore. Elaborate-and-irregular percussion programming; edit-as-instrument aesthetic; headphone-listening orientation.' },
  { id: 'experimentalElec.industrialNoise', name: 'Industrial and noise', parent: 'experimentalElec', description: 'Industrial and noise music: industrial proper, noise, EBM, dark electro, abrasive electronic. Distorted-and-mechanical timbres; transgressive-or-confrontational performance context; refusal of melodic-conventional architecture.' },
  { id: 'experimentalElec.retroAesthetic', name: 'Retro and aesthetic-driven', parent: 'experimentalElec', description: 'Retro-aesthetic electronic music: vaporwave, synthwave, mallsoft, hauntology, retrowave, slushwave. False-memory-of-1980s-or-90s timbral palette; nostalgia-and-irony as primary affect.' },
  { id: 'experimentalElec.popExperimental', name: 'Hyperpop and pop-experimental', parent: 'experimentalElec', description: 'Experimental-leaning pop production: hyperpop, deconstructed club, glitchpop, sigilkore. Pop-song-architecture overloaded with avant-garde production techniques; brick-walled-and-distorted mixing aesthetic; internet-native authorship.' },
  { id: 'experimentalElec.lofi', name: 'Lo-fi production', parent: 'experimentalElec', description: 'Lo-fi aesthetic electronic music: lo-fi proper, lo-fi hip-hop, chillhop, sad lo-fi. Cassette-warble and tape-saturation processing; sample-collage source-material; study-and-sleep listener-context.' },
  { id: 'experimentalElec.musiqueConcrete', name: 'Musique concrète and electroacoustic', parent: 'experimentalElec', description: 'Concrete and electroacoustic composition: musique concrète proper, electroacoustic composition, plunderphonics, modular synthesis, sound collage. Recorded-sound-as-instrument philosophy; academic-or-conservatory-derived institutional context.' },
  { id: 'balladPoetry.angloSingerSong.confessional60s', name: '1960s confessional folk', parent: 'balladPoetry.angloSingerSong', description: 'Greenwich Village and Cambridge Mass folk-revival songwriter mode; 1960s folk-revival confessional-narrative lyric authorship over fingerpicked acoustic guitar.' },
  { id: 'balladPoetry.angloSingerSong.laurelCanyon', name: 'Laurel Canyon', parent: 'balladPoetry.angloSingerSong', description: 'Early-1970s Los Angeles singer-songwriter circle; folk-rock-orchestral arrangements, intimate vocal delivery, autobiographical lyric subjects.' },
  { id: 'balladPoetry.angloSingerSong.britfolk', name: 'British folk-songwriter', parent: 'balladPoetry.angloSingerSong', description: 'UK folk-revival singer-songwriter lineage descended from late-1960s UK folk-revival scene; modal melodic vocabulary, fingerstyle guitar, English-and-Celtic literary heritage.' },
  { id: 'balladPoetry.angloSingerSong.antiFolk', name: 'Anti-folk', parent: 'balladPoetry.angloSingerSong', description: 'New York 1980s lo-fi songwriter scene rejecting folk-revival earnestness; deliberate-amateurism delivery, ironic lyric mode, post-punk-adjacent sensibility.' },
  { id: 'balladPoetry.angloSingerSong.indieFolk', name: 'Indie folk', parent: 'balladPoetry.angloSingerSong', description: '2000s-onward indie-rock-derived songwriter folk; band-arranged production, melancholic-major-key affect, often layered vocal harmonies.' },
  { id: 'balladPoetry.angloSingerSong.freakFolk', name: 'Freak folk', parent: 'balladPoetry.angloSingerSong', description: '2000s psychedelic-folk movement reviving 60s-70s acid-folk aesthetics; orchestral-experimental arrangements, mystic-pastoral lyric subjects.' },
  { id: 'balladPoetry.angloSingerSong.countryFolkStory', name: 'Country-folk storyteller', parent: 'balladPoetry.angloSingerSong', description: 'Country-leaning songwriter tradition emphasizing narrative-character lyric authorship over folk-country accompaniment; Texas songwriter scene.' },
  { id: 'balladPoetry.angloSingerSong.bedroomSingerSong', name: 'Bedroom singer-songwriter', parent: 'balladPoetry.angloSingerSong', description: '2010s-onward DIY-DAW recorded songwriter mode; intimate-vocal-and-guitar arrangements with synth-pad textures, internet-distributed authorship.' },
  { id: 'balladPoetry.celticBalladic.seanNos', name: 'Sean-nós', parent: 'balladPoetry.celticBalladic', description: 'Irish-Gaelic unaccompanied solo-vocal balladic tradition; highly-ornamented melismatic phrasing, modal-and-microtonal melodic vocabulary, regional Connacht-Munster-Donegal style variation.' },
  { id: 'balladPoetry.celticBalladic.bothyBallad', name: 'Bothy ballad', parent: 'balladPoetry.celticBalladic', description: 'Northeast Scottish Doric-language farm-laborer balladry; narrative-male-voice delivery, occupational subject matter, traditionally unaccompanied or with melodeon.' },
  { id: 'balladPoetry.celticBalladic.scottishBallad', name: 'Scottish balladry', parent: 'balladPoetry.celticBalladic', description: 'Lowland Scots and Scottish-Traveller balladic tradition; Child-ballad-canon narrative-songs of supernatural-romantic-historical subjects, often unaccompanied.' },
  { id: 'balladPoetry.celticBalladic.englishBroadside', name: 'English broadside ballad', parent: 'balladPoetry.celticBalladic', description: 'English topical-narrative balladry printed on broadside-sheets and circulated as commercial songsheet from 16th to 19th centuries; tune-borrowing tradition with new-text-set-to-known-tunes.' },
  { id: 'balladPoetry.celticBalladic.welshHymnBallad', name: 'Welsh hymn-balladry', parent: 'balladPoetry.celticBalladic', description: 'Welsh-language religious-and-secular ballad-singing tradition tied to Methodist-revival hymn-singing culture; four-part harmonic singing, cymanfa ganu congregational singing apex.' },
  { id: 'balladPoetry.celticBalladic.capeBretonGaelic', name: 'Cape Breton Gaelic', parent: 'balladPoetry.celticBalladic', description: 'Atlantic-Canada Scottish-Gaelic-language balladic continuation; milling-frolic communal-vocal-percussive table-thumping tradition, narrative subject preserved from 18th-century Scottish emigration.' },
  { id: 'balladPoetry.celticBalladic.newfoundlandRevival', name: 'Newfoundland folk-revival', parent: 'balladPoetry.celticBalladic', description: 'Newfoundland-Irish-and-English-derived balladic tradition centered on outport-fishing-community-song heritage; revival-era band-arrangement of traditional repertoire.' },
  { id: 'balladPoetry.bluesNarrative.deltaNarrative', name: 'Delta narrative', parent: 'balladPoetry.bluesNarrative', description: 'Mississippi-Delta narrative-blues tradition; solo-male-voice with bottleneck-slide-guitar accompaniment, autobiographical-and-cosmological-subject lyric authorship.' },
  { id: 'balladPoetry.bluesNarrative.piedmontNarrative', name: 'Piedmont narrative', parent: 'balladPoetry.bluesNarrative', description: 'Eastern-seaboard fingerpicked-blues tradition emphasizing narrative-and-songster repertoire; Appalachian-foothills geographic axis, alternating-thumb fingerpicking technique foundational.' },
  { id: 'balladPoetry.bluesNarrative.workSong', name: 'Work song', parent: 'balladPoetry.bluesNarrative', description: 'African-American occupational-labor song tradition; lead-and-chorus call-and-response, work-pacing-rhythmic-function, railroad-and-stevedore-and-axe-work subject matter.' },
  { id: 'balladPoetry.bluesNarrative.prisonSong', name: 'Prison song', parent: 'balladPoetry.bluesNarrative', description: 'Southern-US prison-farm-work-song tradition; 20th-century-field-recording archives at Parchman Farm and Angola Penitentiary, lead-and-chorus call-and-response over field-labor pacing.' },
  { id: 'balladPoetry.bluesNarrative.fieldHoller', name: 'Field holler', parent: 'balladPoetry.bluesNarrative', description: 'Solo unaccompanied agricultural-labor vocal-call tradition; melismatic vocal phrasing, microtonal-and-modal blue-note inflection, blues-progenitor sonic territory.' },
  { id: 'balladPoetry.bluesNarrative.hokumBlues', name: 'Hokum blues', parent: 'balladPoetry.bluesNarrative', description: 'Vaudeville-blues sub-tradition emphasizing humorous-double-entendre lyric subjects; jug-band and tight-combo arrangement, urban-cabaret performance scene.' },
  { id: 'balladPoetry.bluesNarrative.jugBand', name: 'Jug band', parent: 'balladPoetry.bluesNarrative', description: '1920s-1930s African-American Memphis-and-Cincinnati blues-and-popular-song sub-tradition using DIY-instrumentation: jug-as-bass-instrument blown for low-register fundamental, washboard for percussion, harmonica, kazoo, guitar, banjo, fiddle; Memphis Jug Band, Cannon\'s Jug Stompers, Gus Cannon, Will Shade as reference; distinct from hokum-blues vaudeville by Memphis-and-rural-Tennessee-circuit performance lineage and lyrical-thematic emphasis on blues-and-folk-narrative rather than vaudeville-double-entendre.' },
  { id: 'balladPoetry.bluesNarrative.classicBluesWomen', name: 'Classic blues women', parent: 'balladPoetry.bluesNarrative', description: 'Vaudeville-era African-American female-vocalist blues tradition; piano-fronted small-jazz-combo accompaniment, TOBA theater circuit and 78rpm race-records context, despairing-and-melismatic emotional register, foundational lineage feeding forward into swing-era jazz vocal and gospel.' },  { id: 'balladPoetry.bluesNarrative.talkingBlues', name: 'Talking blues', parent: 'balladPoetry.bluesNarrative', description: 'Spoken-rhythmic-narrative form descended from country-blues talking; precursor to country talking-song and to early rap; meter-driven story-delivery over chord-progression backing.' },
  { id: 'balladPoetry.chansonFado.classicChanson', name: 'Classic chanson', parent: 'balladPoetry.chansonFado', description: 'Mid-20th-century French chanson canon centered on literary-text-as-foundation aesthetic; mid-20th-century Paris cabaret heritage.' },
  { id: 'balladPoetry.chansonFado.postChanson', name: 'Post-chanson auteur', parent: 'balladPoetry.chansonFado', description: 'Post-1960s French songwriter tradition extending chanson aesthetic with rock-and-pop instrumentation; late-1960s-and-1970s songwriter generation and successors.' },
  { id: 'balladPoetry.chansonFado.fadoCoimbra', name: 'Fado de Coimbra', parent: 'balladPoetry.chansonFado', description: 'Coimbra-university male-student fado tradition; Portuguese-guitar-and-classical-guitar duo accompaniment, university-tradition serenade context.' },
  { id: 'balladPoetry.chansonFado.fadoLisboa', name: 'Fado de Lisboa', parent: 'balladPoetry.chansonFado', description: 'Lisbon urban fado tradition centered on Alfama and Bairro Alto neighborhoods; female-vocal-emphasized, Portuguese-guitar-and-viola accompaniment, saudade-affect lyric mode.' },
  { id: 'balladPoetry.chansonFado.morna', name: 'Morna', parent: 'balladPoetry.chansonFado', description: 'Cape Verdean Lusophone-archipelago melancholic ballad tradition centered on cavaquinho-and-violão-and-violin small-acoustic-ensemble accompaniment; sodade (saudade) emotional register, Cape Verdean Creole lyric language, slow 3/4 or 6/8 tempo, foundational national-genre status for Cape Verde.' },
  { id: 'balladPoetry.chansonFado.greekEntechno', name: 'Greek éntechno', parent: 'balladPoetry.chansonFado', description: 'Greek "art-song" composer tradition setting modern-Greek-poetry to Greek-folk-derived melodic-and-modal materials; mid-20th-century Greek-composer canon, bouzouki-orchestral arrangements.' },
  { id: 'distortedRock.metal.nwobhm', name: 'NWOBHM', parent: 'distortedRock.metal', description: 'New Wave of British Heavy Metal — late-1970s into early-80s UK metal revival; twin-guitar-harmony lead lines, gallop-tempo back-line, fantasy-and-historical lyric subjects.' },
  { id: 'distortedRock.metal.thrash', name: 'Thrash metal', parent: 'distortedRock.metal', description: 'Mid-80s metal sub-style fusing NWOBHM with hardcore-punk speed; palm-muted tremolo-picked riffing, double-bass-pedal back-line, shouted-vocal delivery.' },
  { id: 'distortedRock.metal.death', name: 'Death metal', parent: 'distortedRock.metal', description: 'Late-80s extreme-metal sub-style emphasizing low-tuned-guitar tremolo riffing, blast-beat percussion, and growled-vocal delivery; Florida and Stockholm scenes.' },
  { id: 'distortedRock.metal.black', name: 'Black metal', parent: 'distortedRock.metal', description: 'Late-80s and 90s extreme-metal sub-style emphasizing tremolo-picked atmospheric riffing, blast-beat back-line, shrieked-vocal delivery; Norwegian second-wave.' },
  { id: 'distortedRock.metal.doom', name: 'Doom metal', parent: 'distortedRock.metal', description: 'Slow-tempo down-tuned metal sub-style descended from early-1970s English heavy-blues-rock; massive-distortion-low-tempo riffing, dirge-like song structures, gothic-pessimist lyric subjects.' },
  { id: 'distortedRock.metal.sludge', name: 'Sludge metal', parent: 'distortedRock.metal', description: 'New Orleans-rooted slow-metal sub-style fusing doom with hardcore-punk; massively-distorted riffing, abrasive-shouted vocal delivery, swampy-low-end production aesthetic.' },
  { id: 'distortedRock.metal.drone', name: 'Drone metal', parent: 'distortedRock.metal', description: 'Extreme-minimalist sustained-tone metal sub-style codified by Earth and Sunn O))) from 1993 onward; guitar-as-pure-sustained-tone compositional approach, near-tempo-less timing, hour-long track scale, ritualistic-volume-as-physical-experience performance aesthetic.' },
  { id: 'distortedRock.metal.prog', name: 'Progressive metal', parent: 'distortedRock.metal', description: 'Metal sub-style importing prog-rock compositional ambition; odd-meter passages, virtuoso instrumental displays, long-form song structures.' },
  { id: 'distortedRock.metal.power', name: 'Power metal', parent: 'distortedRock.metal', description: 'European-rooted metal sub-style emphasizing major-key melodic-anthem songwriting; high-tenor lead vocals, gallop-tempo back-line, fantasy-and-mythic lyric subjects.' },
  { id: 'distortedRock.metal.symphonic', name: 'Symphonic metal', parent: 'distortedRock.metal', description: 'Metal sub-style integrating orchestral and choral arrangements with metal back-line; female-soprano operatic-vocal lead common, gothic-or-fantasy lyric subjects.' },
  { id: 'distortedRock.metal.folkMetal', name: 'Folk metal', parent: 'distortedRock.metal', description: 'Metal sub-style integrating regional folk-instrument and folk-melodic-modal vocabulary into metal back-line; Finnish, Celtic, Slavic, and Mediterranean regional variants.' },
  { id: 'distortedRock.metal.postMetal', name: 'Post-metal', parent: 'distortedRock.metal', description: 'Late-90s onward metal sub-style importing post-rock dynamic-arc compositional logic; long-form crescendo-and-release structures, atmospheric guitar-tone exploration.' },
  { id: 'distortedRock.metal.avant', name: 'Avant-garde metal', parent: 'distortedRock.metal', description: 'Experimental-leaning metal sub-style importing avant-garde-and-progressive-classical vocabulary; non-standard song structures, unconventional sound sources.' },
  { id: 'electronicDance.house.chicagoHouse', name: 'Chicago house', parent: 'electronicDance.house', description: 'Original Chicago club-scene house music c.1985-1990; raw 909-and-808 back-line programming, soul-and-disco-derived vocal samples, jacking back-line aesthetic.' },
  { id: 'electronicDance.house.deepHouse', name: 'Deep house', parent: 'electronicDance.house', description: 'Soulful-jazz-derived house sub-style; lush extended-chord harmonic vocabulary, Rhodes-and-pad textures, smooth vocal performances over four-on-floor back-line.' },
  { id: 'electronicDance.house.garageHouseUS', name: 'Garage house (US)', parent: 'electronicDance.house', description: 'New York Paradise-Garage-derived house sub-style; gospel-and-soul vocal performances over more-syncopated four-on-floor back-line, organ-and-piano stab vocabulary.' },
  { id: 'electronicDance.house.microhouse', name: 'Microhouse', parent: 'electronicDance.house', description: 'Late-90s onward minimal-glitch-derived house sub-style; sparse arrangement, micro-detail percussion programming, often-instrumental track-form.' },
  { id: 'electronicDance.house.lofiHouse', name: 'Lo-fi house', parent: 'electronicDance.house', description: '2010s-onward house sub-style with deliberately-degraded production aesthetic; tape-saturation-and-cassette-warble processing, sample-collage source material.' },
  { id: 'electronicDance.house.italoHouse', name: 'Italo house', parent: 'electronicDance.house', description: 'Late-80s and early-90s Italian-developed house sub-style; piano-stab-driven hooks, italo-disco harmonic-progression vocabulary, festive-tempo affect.' },
  { id: 'electronicDance.house.latinHouse', name: 'Latin house', parent: 'electronicDance.house', description: 'House sub-style integrating Latin-percussion programming and Latin-music-derived vocal-and-melodic content; Cuban-Brazilian-Andean source materials reprocessed through house-music production.' },
  { id: 'electronicDance.house.techHouse', name: 'Tech-house', parent: 'electronicDance.house', description: 'House-and-techno hybrid sub-style; minimal-techno percussion programming with house-music groove-and-hook sensibility, club-DJ-scene oriented.' },
  { id: 'ritualDevotional.christianGospel.blackGospel', name: 'Black gospel', parent: 'ritualDevotional.christianGospel', description: 'African-American Pentecostal-and-Baptist sacred song tradition; choir-and-soloist-and-organ ensemble configuration, blues-and-jazz-derived chord vocabulary, ecstatic vocal interpretation.' },
  { id: 'ritualDevotional.christianGospel.spirituals', name: 'African-American spirituals', parent: 'ritualDevotional.christianGospel', description: 'Pre-Emancipation-and-Reconstruction-era African-American sacred song tradition; communal call-and-response and unaccompanied voice or hand-percussion arrangement, biblical-narrative-and-hidden-meaning lyric tradition, foundational lineage to gospel, blues, and jazz.' },
  { id: 'ritualDevotional.christianGospel.jubileeQuartet', name: 'Jubilee quartet', parent: 'ritualDevotional.christianGospel', description: 'Late-19th-and-early-20th-century African-American close-harmony quartet tradition; concert-presentation arranged-spiritual repertoire emerging from Fisk Jubilee Singers 1870s tour and developing into pre-gospel quartet ensemble vocabulary.' },
  { id: 'ritualDevotional.christianGospel.sacredHarp', name: 'Sacred Harp', parent: 'ritualDevotional.christianGospel', description: 'Southern-US shape-note congregational hymn-singing tradition; four-part open-fifth-and-octave-emphasis harmony, hollow-fifth modal voice-leading, all-voices-at-full-volume aesthetic.' },
  { id: 'ritualDevotional.christianGospel.anglicanChoral', name: 'Anglican choral', parent: 'ritualDevotional.christianGospel', description: 'English cathedral-choir tradition; men-and-boys SATB-arrangement performance of psalmody, anthem, and service-music repertoire; 16th-through-20th-century English-polyphonic-and-anthem composer canon.' },
  { id: 'ritualDevotional.christianGospel.russianOrthodox', name: 'Russian Orthodox liturgical', parent: 'ritualDevotional.christianGospel', description: 'Russian Orthodox liturgical chant tradition; unaccompanied SATB-and-bass-octavist choral singing, octoechos modal vocabulary, znamenny chant ancestral lineage.' },
  { id: 'ritualDevotional.christianGospel.coptic', name: 'Coptic liturgical', parent: 'ritualDevotional.christianGospel', description: 'Egyptian Coptic Orthodox liturgical chant tradition; melismatic-modal solo-and-congregational vocal recitation, triangle-and-cymbal punctuation, considered preserving pharaonic-era chant legacy.' },
  { id: 'ritualDevotional.christianGospel.pentecostal', name: 'Pentecostal worship', parent: 'ritualDevotional.christianGospel', description: 'Charismatic-Pentecostal contemporary-worship-music tradition; band-arranged worship songs over rock-derived instrumentation, glossolalia-and-shouting ecstatic vocal moments.' },
  { id: 'ritualDevotional.christianGospel.sacredSteel', name: 'Sacred Steel', parent: 'ritualDevotional.christianGospel', description: 'Pentecostal-Holiness-Church Black-Southern lap-steel-and-pedal-steel-guitar gospel tradition; vocalized-instrumental-mimicry technique, ecstatic-worship congregational context.' },
  { id: 'groovePercussion.cuban.sonSalsa', name: 'Son and salsa lineage', parent: 'groovePercussion.cuban', description: 'Cuban son-cubano and its New York and Cuban salsa descendants; tres-and-piano-driven montuno harmonic-vamp foundation, lead-and-chorus call-and-response architecture.' },
  { id: 'groovePercussion.cuban.rumba', name: 'Rumba lineage', parent: 'groovePercussion.cuban', description: 'Cuban Afro-secular drum-and-vocal rumba traditions; conga-trio-and-claves-and-vocal architecture, three-style yambú-guaguancó-columbia regional variation.' },
  { id: 'groovePercussion.cuban.charangaDanza', name: 'Charanga and danza lineage', parent: 'groovePercussion.cuban', description: 'Cuban formal-court-and-flute-violin-ensemble dance traditions; danzón-and-charanga ancestor-forms, mambo and cha-cha-chá descendants.' },
  { id: 'ritualDevotional.christianGospel.southernGospel', name: 'Southern gospel', parent: 'ritualDevotional.christianGospel', description: 'White-Southern-US gospel sub-tradition descended from Sacred-Harp shape-note congregational singing; quartet and family-group performance format, country-crossover instrumentation.' },
  { id: 'droneModal.heterophonic', name: 'Heterophonic drone-modal', parent: 'droneModal', description: 'Drone-modal music in which multiple voices or instruments simultaneously elaborate the same melodic line with characteristic micro-variations in ornament, rhythm, and pitch-inflection. The drone-and-melodic-elaboration register characteristic of much Central and Inner Asian classical practice and many African and Pacific traditions where multiple singers ornament a shared melodic line.' },
  { id: 'ritualDevotional.indigenous.amazonian', name: 'Amazonian indigenous ritual song', parent: 'ritualDevotional.indigenous', description: 'Amazonian indigenous ritual-song traditions, including shamanic-healing repertoires sung by named healer-figures to individual patients in nocturnal ceremonial contexts. Shipibo icaros are the canonical type-specimen.' },
  { id: 'ritualDevotional.indigenous.mapuche', name: 'Mapuche ritual song', parent: 'ritualDevotional.indigenous', description: 'Mapuche (Araucanian) ritual-song traditions of Argentina and Chile, including the women-led tayil genealogical-chant and the machi shamanic ülkantun.' },
  { id: 'ritualDevotional.indigenous.arctic', name: 'Arctic indigenous song-game', parent: 'ritualDevotional.indigenous', description: 'Arctic indigenous vocal traditions including the Inuit / Iñupiaq / Yupik throat-singing game families (katajjaq, nipaquhiit, and analogous female-duo hocketed inhaled-and-exhaled forms). The now-extinct Ainu rekuhkara is the historical analogue.' },
  { id: 'artMusic.eastAsian.tibetanRitual', name: 'Tibetan ritual art-music', parent: 'artMusic.eastAsian', description: 'Tibetan ritual art-music traditions including ache lhamo opera and the parallel monastic-liturgical repertoires; distinguished from the more directly liturgical yang chant which sits under ritualDevotional.buddhist.' },

  // ============================================================
  // UNIVERSAL-FUNCTION BRANCHES
  // ============================================================
  // Songs organized by the human situation they exist FOR — lullaby, wedding,
  // funeral lament, work-at-sea, etc. — rather than by stylistic lineage.
  // Each top-level branch encodes universal-form musical priors that emerge
  // from the function regardless of culture (lullaby = slow descending narrow-
  // ambitus rocking; lament = ornamented free-meter sliding-into-pitches with
  // sob-glottalization; sea shanty = call-response pull-beat 4/4-or-6/8).
  // Entries beneath each branch are named cultural variants — Spanish nana,
  // German Wiegenlied, Japanese komoriuta — each carrying its cultural-specific
  // priors layered atop the universal frame from the branch description.
  //
  // The matrix opens compositional surface area: function × culture lets a
  // model synthesize "Brazilian lullaby" or "Korean funeral lament" by merging
  // function-priors with culture-priors, addressing cells the stylistic
  // organization can't reach directly.
  // ============================================================

  { id: 'lullaby', name: 'Lullaby', parent: null, description: 'Infant-sleep songs documented across every human culture. Shared musical priors emerge from the function regardless of style: slow tempo around 60-80 bpm, rocking meter in ⁶⁄₈ or ¾ or freely-flowing unmetered phrasing, descending melodic contour, narrow ambitus typically a fifth or sixth, soft intimate dynamic, melisma on long vowels, repetition of a short motif, single-voice register at the head of an infant. The Harvard Music Lab cross-cultural song analysis (Mehr et al, 86 societies) identifies lullaby as one of the three documented musically-universal song-form categories. Named local forms include Spanish nana, German Wiegenlied, Russian колыбельная (kolybelnaya), Italian ninna-nanna, French berceuse, Portuguese acalanto, Yiddish vigndlid, Persian lālā\'ī, Arabic tahwidah, Hindi lori, Tamil thālāttu, Bengali ghum-paranir gan, Mandarin yáolán qǔ (摇篮曲), Korean jajanga (자장가), Japanese komoriuta (子守唄), Yoruba orin omode, Zulu ihubo, Quechua wawa-qhapaq, Hawaiian mele hānau. The cultural variant inflects this universal frame with local modal vocabulary, ornament conventions, performance context (maternal vs. nursemaid, domestic vs. ceremonial), and original-language text. Function-axis branch — pairs with cultural style branches via the Rich tab descriptor merge.' },
  { id: 'lullaby.european', name: 'European lullaby traditions', parent: 'lullaby', description: 'Cradle-song traditions across Romance, Germanic, Slavic, Celtic, and Hellenic Europe. Regional inflection includes Andalusian-Phrygian and Sephardic color (Spanish nana, Sephardic nani-nani), Italian rocking-meter ninna-nanna, German strophic Wiegenlied, Slavic minor-key kolybelnaya, Celtic-Gaelic ornamented melismatic tàladh and suantraí, Greek nanourisma. Across the diversity, a shared ⁶⁄₈ rocking or free-meter pattern, intimate maternal-singing context, descending-contour melodic shape.' },
  { id: 'lullaby.eastAsian', name: 'East Asian lullaby traditions', parent: 'lullaby', description: 'Cradle-song traditions across the Chinese, Korean, and Japanese cultural sphere. Shared traits: pentatonic-leaning melodic vocabulary, narrow ambitus often within a sixth, syllabic onomatopoeic refrain (yáolán qǔ, jajanga, komoriuta), pentatonic-modal scale framework (Chinese gong, Japanese in or yo, Korean minsogak), gentle ornament rather than European-style melisma.' },
  { id: 'lullaby.southAsian', name: 'South Asian lullaby traditions', parent: 'lullaby', description: 'Cradle-song traditions across Hindi-Urdu, Tamil, Bengali, and broader South Asian linguistic-cultural zones. Defined by raga-adjacent melodic vocabulary inflecting the lullaby frame (Yaman, Bhairavi, and other tender-affect ragas common in lori practice), free-meter alap-like opening with rocking metric body, occasional harmonium drone accompaniment in domestic-classical context, intimate maternal-and-grandmother singing tradition. Tamil thālāttu and Hindi lori are dictionary-level vocabulary items signaling deep cultural-categorical embedding.' },
  { id: 'lullaby.middleEastern', name: 'Middle Eastern lullaby traditions', parent: 'lullaby', description: 'Cradle-song traditions across Persian, Arabic, and Levantine cultural zones. Defined by maqam-melodic-vocabulary inflecting the lullaby frame (Bayāti, Saba, and other tender-affect maqamat common in tahwidah and lālā\'ī practice), microtonal pitch inflection, free-meter or slow-rocking metric body, vocal-melisma-as-tenderness register, often unaccompanied or with a barely-audible drone, intimate maternal-singing context.' },

  { id: 'wedding', name: 'Wedding music', parent: null, description: 'Music for the wedding ceremony and feast as functional category, documented in nearly every culture with marriage rites. Shared musical priors: festive uptempo, processional element marking entrance or departure of the couple, ornamented melismatic vocal showcasing skilled singers, dense ensemble texture marking celebration, mode-shift or modulation marking ritual transition. Named local repertoires include Yiddish wedding bulgar and freylekhs (klezmer rep), Persian aroosi with daf and tar, Lebanese-and-Egyptian wedding takht, Greek gamilio glendi, Roma svatba and Balkan wedding-fanfara brass, Chinese xǐqìng (喜慶) and suona serenade, Korean kihon yeokli, Andean matrimonio huayno, Sardinian wedding cantu a tenore, Albanian dasma with çifteli, Indian sangeet pre-wedding women\'s songs and baraat groom-procession, Yoruba aso ebi unified-dress celebration songs, Berber wedding ahidus, Ashkenazi mazel tov mainline rep, Jewish sephardic gelilah. Wedding traditions almost always involve a specific instrumentation (klezmer, takht, mariachi, suona ensemble) that distinguishes wedding repertoire from generic celebration. Function-axis branch — entries inflect the universal-celebration frame with culturally-specific instrumentation, vocal practice, and song-form conventions.' },
  { id: 'wedding.european', name: 'European wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Ashkenazi-Jewish, Roma-Balkan, Hellenic, Romance-Mediterranean, Sardinian, Albanian, and Slavic Europe. Defined by ensemble-driven dance-music traditions (klezmer for Yiddish weddings, Balkan brass for Roma svatba, Sardinian launeddas/tenores for Sardinian weddings), highly-ornamented melodic vocabulary, characteristic regional mode-and-meter conventions, festive uptempo dance-foreground arrangements with processional moments marking ritual transitions.' },
  { id: 'wedding.middleEastern', name: 'Middle Eastern and North African wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Persian, Arabic, Levantine, Maghrebi, and Berber cultural zones. Defined by takht-style ensemble (oud, qanun, riq, nay), daf-and-tof percussion-driven dance-music, maqam-or-dastgāh modal vocabulary, vocal-and-dance combined celebration with ululation (zaghareet) as the canonical celebratory vocalization, and culturally-coded wedding-music repertoire distinct from secular concert traditions.' },
  { id: 'wedding.southAsian', name: 'South Asian wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Hindi-Urdu, Punjabi, Tamil, Bengali, and broader South-Asian cultural zones. Defined by the multi-day ceremonial structure (sangeet pre-wedding women\'s music night, baraat groom-procession with brass-and-shehnai-and-dhol, varied ceremonial moments), shehnai-and-dhol-and-tabla-and-harmonium ensemble, raga-derived melodic vocabulary, Hindustani-and-filmi-pop crossover, characteristic celebratory mode and dholak rhythmic foundation.' },
  { id: 'wedding.eastAsian', name: 'East Asian and Southeast Asian wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Chinese, Korean, Japanese, Javanese, and broader East-and-Southeast-Asian cultural zones. Defined by characteristic ensemble (Chinese suona-and-percussion, Javanese gamelan, Korean traditional ensemble), pentatonic-or-cultural-modal vocabulary, ceremonial-and-celebratory dual-function (some pieces processional and formal, others dance-and-feast-oriented).' },
  { id: 'wedding.africanDiasporic', name: 'African and Afro-diasporic wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Yoruba, Akan, Ethiopian, broader Sub-Saharan-African, and Afro-diasporic cultural zones. Defined by call-and-response group-vocal participation, talking-drum-and-percussion ensemble, characteristic unified-dress (aso ebi) celebration-vocal practice, Ethiopian eskista shoulder-dance music, and broader Afro-diasporic-Atlantic wedding-celebration traditions integrating Indigenous-African and post-Atlantic-trade hybridization.' },
  { id: 'wedding.americas', name: 'Americas wedding traditions', parent: 'wedding', description: 'Wedding-music traditions across Andean, Brazilian, Mexican, and broader Latin-American-and-Caribbean cultural zones. Defined by characteristic ensemble (Andean quena-and-charango huayno, Mexican mariachi-and-banda, Brazilian forró-and-sertanejo, Caribbean kompa-and-merengue), Spanish-and-Portuguese-language and Indigenous-language coexistence, dance-foreground celebratory arrangement.' },

  { id: 'funeralLament', name: 'Funeral lament and dirge', parent: null, description: 'Mourning-songs at the death of a person, documented as a continuous tradition in most cultures with elaborated death rites. Shared musical priors: slow free-meter or unmetered phrasing, ornamented melisma, microtonal pitch-bending (the so-called "crying interval"), pitches approached from below, sob-glottalization technique, women\'s-voice tradition in the majority of cultures (professional mourner roles documented in Mediterranean, Levant, South Asia, West Africa, East Asia), vocal-forward delivery with sparse or no instrumental accompaniment, mode-leaning toward hijaz / Phrygian / lowered-second-and-sixth registers, text-content of praise-of-the-deceased crossed with grief and reproach. Named local forms include Irish caoineadh (keening, performed by bean chaointe professional keening women), Scottish coronach, Welsh galarnad, Greek moirológi (μοιρολόγι), Sardinian atítidu, Corsican voceru, Romanian bocet, Bulgarian oplakvanje, Albanian vajtim, Russian plach, Finno-Karelian itkuvirsi, Estonian itkulaul, Egyptian na\'i, Sudanese naysha, Hebrew qinah (קינה), Persian rowzeh-khwāni (Shi\'a Muharram lament), Tamil oppāri, Telugu rōdana, Hawaiian kanikau, Maori waiata tangi, Yoruba iremoje (hunters\'-wives funeral dirges), Akan-Asante adesua. The "crying" musical signature is one of the strongest cross-culturally shared vocal-technical features anywhere in the world\'s music.' },
  { id: 'funeralLament.european', name: 'European lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Celtic, Hellenic, Romance-Mediterranean, Balkan, Slavic, and Finno-Ugric Europe. Defined by professional-mourner cultural role (bean chaointe in Ireland, moirológistries in Greece, prefiche in Italy, bocitoare in Romania), women\'s-voice primary tradition, free-meter ornamented melisma, characteristic descending wail with microtonal pitch-bending. The Mediterranean ring of lament cultures (Greek, Sardinian, Corsican, Albanian, Romanian) preserves the densest continuous tradition into modern times.' },
  { id: 'funeralLament.middleEastern', name: 'Middle Eastern lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Persian, Arabic, and Hebrew cultural zones. Defined by maqam or dastgāh modal-vocabulary (Hijaz, Bayāti, Saba especially), professional-mourner role (na\'iha in Arabic culture, rowzeh-khwān in Shi\'a Persian Islamic context), microtonal pitch inflection, free-meter melismatic phrasing, occasional integration with religious-liturgical lament practice (the Shi\'a Muharram lament cycle is the most elaborated codified continuous tradition).' },
  { id: 'funeralLament.southAsian', name: 'South Asian lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Tamil, Telugu, Hindi-Urdu, Bengali, and broader South-Asian cultural zones. Defined by women\'s-voice tradition (oppāri-singers in Tamil culture being the canonical professional mourners), raga-adjacent melodic vocabulary, free-meter melismatic phrasing, characteristic sobbing-into-pitch vocal-technique, lyric content centered on praise-of-the-deceased crossed with grief at the survivor\'s loss.' },
  { id: 'funeralLament.eastAsian', name: 'East Asian lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Korean, Chinese, and Japanese cultural zones. The Korean kok (곡) wailing-at-the-funeral tradition is the most codified, with documented ritual-stages and gendered-role conventions; Chinese ku-mu (哭母) and Japanese funeral chanting are less elaborated than Korean practice but retain core features of female-voice wailing-into-pitch and free-meter melisma.' },
  { id: 'funeralLament.africanDiasporic', name: 'African and Afro-diasporic lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Yoruba, Akan, and broader West-African and Afro-diasporic cultural zones. The Yoruba iremoje hunters\'-funeral tradition (also performed by widows of deceased hunters) is the canonical example with professional-singer codification and Yoruba-language elaborated text-tradition. Akan-Asante adesua dirges and broader Sub-Saharan funeral-song practice continues in the Afro-diasporic Atlantic world.' },
  { id: 'funeralLament.oceaniaPacific', name: 'Oceania and Pacific lament traditions', parent: 'funeralLament', description: 'Mourning-song traditions across Polynesian, Melanesian, and Micronesian cultural zones. Hawaiian kanikau (the named mourning-chant for a deceased chief or beloved person), Maori waiata tangi (mourning-songs performed at tangihanga funeral rites), and broader Pacific-Islander funeral-song practice. Defined by oratorical free-meter recitation, deceased-praise lyric foreground, ritual-bounded performance context.' },

  { id: 'seaShanty', name: 'Sea shanty and maritime work song', parent: null, description: 'Songs sung at coordinated shipboard work — hauling halyards, working capstans, pumping bilges, rowing — documented in maritime cultures globally. Shared musical priors: solo-call vs. crew-response architecture with the soloist (shantyman) leading and the crew answering in unison, pull-beat or push-beat clearly marked at the coordination point of the work, meter typically 4/4 for short-haul or 6/8 for long-haul, melody durable across the variable voices of an untrained crew, lyrical content narrative or bawdy or grievance-airing under cover of the work, tempo set by the work-pace, refrain structure permitting infinite verse-improvisation. Named local repertoires include English halyard and capstan and pump shanties (Drunken Sailor, Leave Her Johnny, Shenandoah, Haul Away Joe), American clipper-ship rep, Norwegian skipperslåtter, Russian Эй, ухнем (Volga boat-haulers\' song), Greek nautical tabachaniotika, Newfoundland outport sea songs, Cape Verdean funaná with maritime themes, Hebridean Gaelic iorram rowing-songs, Faroese kvæði on the open boat. The genre had a global commercial revival in 2021 via the TikTok shanty wave centered on Nathan Evans\'s Wellerman recording. Function-axis branch — distinct from the protest, drinking, and ballad traditions that share some lyrical surface but lack the work-coordination function.' },

  { id: 'fieldWork', name: 'Field-work and harvest song', parent: null, description: 'Songs sung at agricultural labor — planting, reaping, threshing, treading, hoeing — documented throughout agricultural cultures globally. Shared musical priors: medium-slow tempo matched to the physical motion (scything, hoeing, planting), call-and-response between leader and group, pentatonic or modal scale vocabulary, often heterophonic when sung in groups, long-form structure surviving day-long labor, melodically simple but textually elaborate, refrain durable across infinite verses. Often accompanied by no instrument or by a single drum signaling work-pace. Named local repertoires include Mississippi Delta field hollers (the foundational American example, antecedent to blues), Bulgarian zhetvarski pesni (harvest-women\'s songs), Russian zhnitvenye pesni, Romanian colinde de seceriș, Hungarian aratónóta, Greek therizmós, Mande and Wolof West-African harvest rep, Andean Quechua huayno-trabajo, Chinese rice-planting chāyāng diào (插秧调), Korean nongak agricultural drumming with song, Vietnamese hò boat-rowing and rice-paddy songs, Bengali bhatiali (river-boatmen of the Padma). The work-song function is foundational to multiple major secular genres: American blues descends from field-holler practice, Brazilian samba retains rural-Afro-Bahian agricultural-work-song memory, much of Mande popular music traces to harvest and praise repertoires.' },

  { id: 'domesticRhythm', name: 'Domestic rhythm and craft-work song', parent: null, description: 'Songs sung at rhythmic domestic-craft labor — spinning, weaving, fulling cloth, grinding grain, churning butter — documented predominantly in women\'s repertoires across rural cultures globally. Shared musical priors: repetitive rhythmic cell synced to a physical motion (treadle, beat-back at the loom, twist of the spindle, grindstone rotation), narrow ambitus permitting conversation between verses, women\'s-voice tradition nearly universal, long-form extensible structure stretching across hours of labor, often heterophonic when groups work together (waulking the tweed, communal grain-grinding), light or absent instrumental accompaniment with the work-implement itself providing percussion. Named local repertoires include Hebridean Scottish Gaelic waulking songs / òrain luaidh (women\'s tweed-fulling at the table), Irish amhráin saothair including spinning songs, Korean baengnyŏn ga (loom rep), Sami women\'s vuolle during reindeer-tracking and domestic work, Faroese kvæði domestic variants, Romanian cântece de tors la fus (spinning songs), Sardinian boci de tela, Lithuanian raudai domestic variants, Yiddish women\'s spinning-and-lullaby blended rep, Wolof and Mande women\'s grain-grinding rep, Bengali jata-gita grinding-stone songs.' },

  { id: 'huntingSong', name: 'Hunting and tracking song', parent: null, description: 'Songs sung in connection with hunting — for the pursuit, for the prey-call, for the post-hunt celebration, for the medicine ritual surrounding the kill — documented in hunter-gatherer and traditional-agricultural cultures globally. Shared musical priors: imitative (onomatopoeia of prey-calls, terrain-sounds, pursuit footfall), often incorporating whistled or non-pitched vocal elements, episodic narrative structure tracing the hunt as event, polyphonic when sung by groups (the BaAka pygmy hunting polyphony is the type-specimen of dense interlocking hocketed hunting-song), often containing secret knowledge restricted to the hunters\' guild and not recordable for outsiders, ritual-bounded performance contexts. Named local traditions include BaAka pygmy hunting polyphony, San bushman gemsbok and eland songs, Mongolian khoomei in its hunting-call origin, Sami luohti and yoik tracking-songs, Maori karanga manu bird-calling, Mexica and Aztec hunting songs in surviving Cantares Mexicanos, Apache and Lakota hunting medicine songs, Korean nongak with hunting-procession elements, Yoruba iremoje hunters\' guild songs (also funeral function), Aboriginal Australian songlines encoding tracking-geography of hunting country.' },

  { id: 'nurseryRhyme', name: 'Nursery rhyme and children\'s play-song', parent: null, description: 'Songs of childhood play, hand-clap games, jump-rope, ring-games, counting-out — documented across every literate culture and most non-literate ones. Shared musical priors: narrow range typically pentatonic or hexatonic, repeating short melodic cell durable in oral transmission across generations, falling cadence as universal feature, action-coordination structure (clapping pattern, circle-game motion, jump-rope timing, finger-game), simple text-setting one-note-per-syllable, durable across centuries (many English nursery rhymes traceable to medieval or early-modern origin). Mehr et al\'s cross-cultural song analysis identifies children\'s play-song as one of the three documented musically-universal song-form categories. Named local repertoires include English nursery rhymes (Hot Cross Buns, Ring Around the Rosie, Mary Had a Little Lamb), French comptines (Frère Jacques, Sur le pont d\'Avignon, Au clair de la lune), German Kinderlieder and Abzählreime (Hoppe hoppe Reiter, Backe backe Kuchen), Italian filastrocche (Giro giro tondo), Spanish and Mexican rondas (Naranja dulce, La víbora de la mar), Korean dongyo (동요), Japanese warabe-uta (童歌, Tōryanse, Kagome), Mandarin tóngyáo (童謠, Liǎng zhī lǎohǔ), Russian poteshki and pestushki, Romanian cântece pentru copii, Yoruba ọmọ-iya nursery rep, Lebanese-and-Egyptian aghani al-atfal, Hindi Lakdi ki kathi and Chubby Cheeks-era school-rhyme rep.' },
  { id: 'nurseryRhyme.european', name: 'European nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across English, French, German, Italian, Spanish, Russian, Polish, and broader European cultural zones. Defined by narrow-range pentatonic-or-hexatonic melodic vocabulary, durable-oral-transmission across centuries (the Iona and Peter Opie Lore and Language of Schoolchildren documentation), action-coordination structure (clapping, jumping, circle-game motion), and characteristic European language-specific text register (Frère Jacques, Hoppe hoppe Reiter, Giro giro tondo).' },
  { id: 'nurseryRhyme.eastAsian', name: 'East Asian nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across Korean dongyo (동요), Japanese warabe-uta (童歌), and Mandarin tóngyáo (童謠) cultural zones. Defined by pentatonic melodic vocabulary, tonal-language-constrained melody-locked-to-speech-tone in Mandarin and Cantonese variants, action-coordination structure (the Japanese kagome circle-game, the Korean ganggangsullae circle-game), and culturally-specific text register including hand-game-and-finger-game accompaniment songs.' },
  { id: 'nurseryRhyme.southAsian', name: 'South Asian nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across Hindi-Urdu, Tamil, Bengali, Punjabi, and broader South-Asian cultural zones. Defined by simple-pentatonic melodic vocabulary, action-coordination structure, and characteristic South-Asian-language text register (the Hindi Lakdi ki kathi and Hum honge kamyab repertoire foundational to modern Indian school-curriculum-children\'s-songs).' },
  { id: 'nurseryRhyme.middleEastNAfrican', name: 'Middle Eastern and North African nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across Lebanese-Egyptian-Levantine Arabic, Persian, Turkish, and broader Middle-Eastern-and-North-African cultural zones. Defined by maqam-or-modal-folk melodic vocabulary, Arabic-and-Persian-and-Turkish language text register, action-coordination structure, frequently religious-festival-and-family-celebration integrated children\'s-song repertoire.' },
  { id: 'nurseryRhyme.subSaharanAfrican', name: 'Sub-Saharan African nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across Yoruba, Akan, Zulu, Mande, and broader Sub-Saharan-African cultural zones. Defined by call-and-response group-vocal participation, tonal-language-constrained melody (in tonal-language traditions), characteristic clapping-and-rhythmic-foot-stamping accompaniment, group-game social context.' },
  { id: 'nurseryRhyme.americas', name: 'Americas nursery rhyme traditions', parent: 'nurseryRhyme', description: 'Children\'s play-song traditions across English-American, Mexican-Spanish ronda, Brazilian Portuguese, Andean Quechua, and Caribbean cultural zones. Defined by adaptation-and-hybridization of European-imported children\'s-song repertoires with Indigenous-and-Afro-diasporic musical influences, English-Spanish-Portuguese-and-Indigenous-language text register, characteristic action-coordination including circle-game (the Mexican La víbora de la mar) and hand-game (the American-English Miss Mary Mack) structures.' },

  { id: 'drinkingSong', name: 'Drinking song and tavern song', parent: null, description: 'Songs sung in the social drinking context — taverns, beer-halls, university beer-cellars, after-feast gatherings, kafenia — across most cultures with developed alcohol traditions. Shared musical priors: choral or unison group voice with everyone joining the refrain, refrains designed for crowd-participation under progressive cognitive impairment (simple melodically, harmonically anchored), lyrical themes around alcohol or fellowship or lost-love or political grievance, mode often modal-major or with raised-fourth giving the "tavern" color (Western examples lean Mixolydian or Dorian), tempo medium-slow as the night wears on, clink-of-glass percussion implicit, leader-and-crowd verse-and-chorus alternation. Named local repertoires include German Trinklied and Trinkspruch (university Kommerslieder, Bavarian Schunkellieder), Russian застольная (zastolnaya, "table-song"), Irish pub song / Whiskey in the Jar / The Wild Rover rep, Scottish bothy ballad rep crosses into bothy drinking song, French chansons à boire, Italian canti goliardici (medieval student drinking rep) and canzoni da osteria, Greek symposion-tradition continuing in rebetiko\'s drinking themes and the kafenío repertoire, Czech pijácká, Hungarian bordal, Polish biesiadne, Mexican cantina rep within rancheras, Korean jubu-ga (酒夫歌), Japanese izakaya rep including modern enka standards adopted for drinking-session use.' },
  { id: 'drinkingSong.european', name: 'European drinking-song traditions', parent: 'drinkingSong', description: 'European drinking-song traditions across German Trinklied, Russian zastolnaya, Irish pub session-song, French chansons à boire, Italian canti goliardici, Scottish bothy ballad, Czech-Polish-Hungarian biesiadne pijacka bordal corpora.' },
  { id: 'drinkingSong.balkan', name: 'Balkan tavern-and-kafana song traditions', parent: 'drinkingSong', description: 'Balkan tavern-and-kafana drinking-song traditions across Macedonian, Serbian, Albanian, Bulgarian, Romanian, and broader South-Slavic-and-Balkan cultural zones.' },
  { id: 'drinkingSong.eastAsian', name: 'East Asian drinking song traditions', parent: 'drinkingSong', description: 'East-and-Southeast-Asian drinking-song traditions across Korean jubu-ga, Japanese izakaya-and-enka, Chinese tavern-song, and broader Asian alcohol-consumption-context rep.' },
  { id: 'drinkingSong.americas', name: 'Americas drinking song traditions', parent: 'drinkingSong', description: 'Americas drinking-song traditions across Mexican cantina rep, American-country honky-tonk-and-cowboy drinking-song, Brazilian boteco rep, Caribbean rum-shop song.' },

  { id: 'carnivalProcessional', name: 'Carnival and festival processional music', parent: null, description: 'Music for the costumed-festival procession or parade — Carnival before Lent, harvest festivals, patron-saint days, royal-or-civic processions — documented in every culture with elaborated annual festival cycles. Shared musical priors: marching-tempo meter (2/4 cut-time or 6/8 march-feel), brass-or-drum foreground for outdoor projection, dense ensemble texture (full school, full band, full orchestra of drummers), call-and-response group-vocals supporting the lead instrumental voice, sustained-energy across hours of procession, characteristic instrument (samba bateria, mariachi banda, trumpet-and-drums brass-band, taiko ensemble), costumes-and-masks integral to the music-as-performance. Named local repertoires include Trinidad Carnival road-march and pan-yard rep (calypso and soca as the song-form), Brazilian Carnaval samba-school bateria with the enredo theme-song, New Orleans Mardi Gras Indians (distinct from second-line and Dixieland), Mardi Gras Indians chant tradition, Cologne and Rhineland Karneval, Caribbean junkanoo (Bahamas, Belize), Cape Verdean kavalu fogu, Bolivian diablada of Oruro, Peruvian Virgen del Carmen festival processionals, Korean daeboreum lunar-new-year and Japanese matsuri with taiko-and-fue, Venice Carnevale, Aalst Carnival in Belgium, Indian Diwali and Holi processionals with shehnai and dhol.' },

  { id: 'praiseSong', name: 'Praise song and naming-honor song', parent: null, description: 'Songs of formal praise — for ancestors, royalty, patrons, deities, the dead, the newborn, the wedding couple — documented across most stratified-society cultures and many egalitarian ones. Shared musical priors: virtuosic vocal foreground often with professional praise-singers as a hereditary or guild role (griot, jeli, oríkì-chanter, izibongo-reciter), ornamented melismatic delivery, free-meter declamatory style permitting extensive name-list interpolation, audience-response with patron-name punctuation, names-and-titles foregrounded in the text often delivered in deliberate slow enunciation, melodic emphasis on the praise-name itself, accompaniment often by a single melodic instrument (kora, ngoni, lute, lyre) supporting the voice. Named local repertoires include Mande and Wolof West-African jeli / griot praise rep (already partly covered in catalog under balladPoetry.westAfricanGriot), Yoruba oríkì (praise-poetry naming the praise-receiver), Hindu stuti and kirtana praise-rep (partly covered), Tibetan thödröl praise-recitation, Welsh moliannu, Akan-Asante kete royal praise, Zulu izibongo (the Zulu praise-poetry tradition), Sotho dithoko, Korean pansori-adjacent praise scenes, Hawaiian mele inoa (name-songs naming a chief or place), Sufi munajat devotional-praise to God.' },
  { id: 'praiseSong.subSaharanAfrican', name: 'Sub-Saharan African praise-song traditions', parent: 'praiseSong', description: 'Praise-song traditions across Mande-Wolof West-African griot/jeli lineage, Yoruba oríkì, Akan-Asante kete royal-praise, Zulu izibongo, Sotho dithoko, Shona and Ndebele praise-song; defined by hereditary praise-singer professional roles, virtuosic name-and-genealogy declamation, characteristic instrumental accompaniment (kora, ngoni, balafon for Mande; talking-drum for Yoruba; mbira for Shona).' },
  { id: 'praiseSong.indianSubcontinent', name: 'Indian subcontinent praise traditions', parent: 'praiseSong', description: 'Praise-song traditions across Hindu, Sikh, Sufi-Muslim, and Jain South-Asian devotional contexts: Hindu stuti and bhajan praise of deities, Sikh shabad kirtan, Sufi munajat and naat praise of God-and-Prophet, Tibetan-Buddhist thödröl praise of bodhisattvas and lamas. Defined by raga-derived melodic vocabulary, harmonium-and-tabla-and-tambura ensemble (in Indian-classical-aligned variants), text-foreground vocal declamation, devotional-and-praise lyric content.' },
  { id: 'praiseSong.celticBritish', name: 'Celtic and British praise traditions', parent: 'praiseSong', description: 'Praise-song traditions across Welsh, Scottish-Gaelic, and broader British-Celtic contexts: Welsh moliannu (the medieval-and-early-modern Welsh praise-poetry tradition continuous through cerdd dant penillion-singing), Scottish Gaelic clan-praise, Irish bardic praise (panegyric tradition predating the suantraí-goltraí-geantraí classification). Defined by harp-and-voice ensemble, Welsh-and-Gaelic-language text register, hereditary-bardic professional role.' },
  { id: 'praiseSong.oceaniaPacific', name: 'Pacific praise traditions', parent: 'praiseSong', description: 'Praise-song traditions across Hawaiian, Maori, Tongan, and broader Polynesian-Pacific contexts: Hawaiian mele inoa (name-songs naming a chief, place, or person), Maori waiata mōteatea-tradition encompassing patere and pao praise-recitations, Tongan langa praise-poetry. Defined by oratorical free-meter declamation, oli-chant vocal practice, name-and-genealogy foregrounded lyric content.' },
  { id: 'praiseSong.middleEastNAfrican', name: 'Middle Eastern and North African praise traditions', parent: 'praiseSong', description: 'Praise-song traditions across Sufi-Islamic, Arabic-language, and Berber-Amazigh contexts: Sufi naat-and-munajat praise of God-and-Prophet, Arabic madh and qasida praise-poetry traditions, Berber-Amazigh praise-poetry. Defined by oud-and-voice or unaccompanied-voice arrangement, classical-Arabic-and-Tamazight literary text register, melismatic vocal practice.' },

  { id: 'protestSong', name: 'Protest song and topical song', parent: null, description: 'Songs of political-and-social grievance — labor protest, anti-war, anti-colonial, civil-rights, revolutionary — documented primarily from the late-18th century forward in the modern political tradition though with older Romantic-era and revolution-era roots. Shared musical priors: strophic verse-chorus song-form for crowd-singability, accessible melodic range within a tenth, lyric foregrounded against sparse accompaniment (typically solo voice with acoustic guitar, or unaccompanied), mode bright-major or folk-modal, narrative or anthemic textual mode (an-it-happened-to-me verse vs. we-shall-overcome chorus), often built on adapted pre-existing tunes from hymnal or folk repertoire for instant adoption. Named local repertoires include the American folk-revival protest tradition (Pete Seeger, Woody Guthrie, Joan Baez, early Bob Dylan, Phil Ochs, Joe Hill IWW rep), Chilean nueva canción (Víctor Jara, Violeta Parra, Inti-Illimani), Argentine canto nuevo (Mercedes Sosa), Italian canti partigiani (Bella Ciao and the Resistance songbook), Portuguese música de intervenção (José Afonso, Grândola Vila Morena — the song that triggered the 1974 Carnation Revolution), South African freedom songs (toyi-toyi, Senzeni Na, Asimbonanga), Korean minjung gayo (민중가요, 1980s democracy-movement rep), Catalan Nova Cançó (Lluís Llach, Raimon), Algerian raï politicization, Egyptian Sayyed Darwish-and-Sheikh-Imam rep, Russian bardovskaya (already in catalog), Polish poezja śpiewana, Basque kantautor (already in catalog), Vietnamese nhạc phản chiến anti-war rep.' },
  { id: 'protestSong.angloAmerican', name: 'Anglo-American protest song', parent: 'protestSong', description: 'American and Anglosphere protest-song traditions: Joe Hill IWW labor anthems (early-20th-century), 1930s topical-song lineage (Almanac Singers, Woody Guthrie), 1960s civil-rights-and-anti-war folk-revival (Pete Seeger, Joan Baez, early Bob Dylan, Phil Ochs, Tom Paxton), broader Anglosphere folk-protest lineage extending through Billy Bragg, Christy Moore, Ewan MacColl, and the modern indie-protest singer-songwriter scene. Defined by acoustic-guitar-and-voice foreground arrangement, narrative verse-chorus song-form, English-language literary-text register.' },
  { id: 'protestSong.iberianLatin', name: 'Iberian and Latin American protest song', parent: 'protestSong', description: 'Iberian-and-Latin-American protest-song traditions: Chilean nueva canción (Víctor Jara, Violeta Parra, Inti-Illimani), Argentine canto nuevo and Mercedes Sosa, Brazilian MPB-era protest (Chico Buarque, Caetano Veloso during the 1968-1985 dictatorship), Catalan Nova Cançó (Lluís Llach, Raimon), and Spanish-and-Portuguese songwriter-protest traditions. Defined by acoustic-guitar-and-charango-and-quena instrumental palette (in the Latin-American lineage) or acoustic-guitar-and-voice songwriter-format (in the Iberian lineage), Spanish-Portuguese-Catalan literary-text register, political-grievance lyric foreground, frequently inflected by Indigenous-language and Indigenous-modal-music integration in the Andean lineage.' },
  { id: 'protestSong.european', name: 'European protest song', parent: 'protestSong', description: 'European protest-song traditions: Italian canti partigiani (Bella Ciao and the Italian Resistance songbook), Portuguese música de intervenção (José Afonso, Grândola Vila Morena), Greek éntechno politicized (Mikis Theodorakis era), Polish poezja śpiewana (Jacek Kaczmarski Solidarność-era), Irish rebel songs (post-1798 through Easter Rising and Troubles), French chanson engagée. Defined by acoustic-guitar-and-voice songwriter-format predominantly, occasional folk-instrument integration (Greek bouzouki, Irish bodhrán), European-language literary-text register, political-grievance and historical-memorial lyric content.' },
  { id: 'protestSong.middleEastNAfrican', name: 'Middle Eastern and North African protest song', parent: 'protestSong', description: 'Middle-Eastern-and-North-African protest-song traditions: Egyptian Sayyed Darwish (early-20th-century musical pioneer who composed in support of the 1919 Egyptian Revolution) and Sheikh Imam lineage, Algerian raï politicization (Cheb Khaled era and earlier), Lebanese-Palestinian protest-song. Defined by maqam-melodic-vocabulary, oud-and-voice arrangement, Arabic-language literary-text register, anti-colonial and social-grievance lyric content, frequently censorship-faced under authoritarian regimes.' },
  { id: 'protestSong.eastAsian', name: 'East Asian and Southeast Asian protest song', parent: 'protestSong', description: 'East-and-Southeast-Asian protest-song traditions: Korean minjung gayo (민중가요, 1980s democracy-movement rep including "Imjin River" and "Marching for our beloved"), Vietnamese nhạc phản chiến anti-war rep (1960s-1975 era including Trịnh Công Sơn), Filipino EDSA-era protest songs, broader East-Asian student-movement protest-song traditions. Defined by acoustic-guitar-and-voice songwriter-format or group-vocal crowd-anthem format, Korean-and-Vietnamese-and-Tagalog-and-other-Asian-language literary-text register, political-grievance and democracy-movement lyric content.' },
  { id: 'protestSong.subSaharanAfrican', name: 'Sub-Saharan African protest song', parent: 'protestSong', description: 'Sub-Saharan African protest-song traditions: South African anti-apartheid freedom songs (toyi-toyi marching-chant, "Senzeni Na?" "Nkosi Sikelel\' iAfrika" "Asimbonanga"), Zimbabwean liberation-war chimurenga, Mozambican Frelimo songs, Nigerian Fela Kuti-era Afrobeat-protest. Defined by group-vocal call-and-response participation, harmony-singing in the South-African tradition, characteristic anti-colonial and anti-apartheid lyric content, integration with movement-marching and group-chant practice.' },
  { id: 'protestSong.urbanAmerican', name: 'Urban American political hip-hop', parent: 'protestSong', description: 'American political hip-hop tradition: Public Enemy late-1980s political-rap canonical, KRS-One Boogie Down Productions conscious-rap, A Tribe Called Quest and the Native Tongues collective, Rage Against the Machine rap-rock-protest hybrid, Mos Def and Talib Kweli Black Star era, modern conscious-rap from Kendrick Lamar and J. Cole and Killer Mike. Defined by sampling-and-breakbeat instrumental foundation, rapped-rhythmic-spoken-flow vocal foreground, political-and-social-grievance lyric content, hip-hop-cultural production-and-distribution context.' },
  { id: 'seaShanty.atlantic', name: 'North Atlantic sea shanty', parent: 'seaShanty', description: 'English, American, Newfoundland, and broader North-Atlantic sea-shanty tradition with halyard, capstan, and pump-shanty forms.' },
  { id: 'seaShanty.mediterranean', name: 'Mediterranean maritime song', parent: 'seaShanty', description: 'Greek tabachaniotika, Cape Verdean funaná maritime, and broader Mediterranean-and-Macaronesian maritime-work-song traditions.' },
  { id: 'seaShanty.northSeaBaltic', name: 'North Sea and Baltic maritime song', parent: 'seaShanty', description: 'Norwegian skipperslåtter, Russian Volga boat-haulers\' songs, Hebridean Gaelic iorram, Faroese kvæði, and broader Northern-European maritime traditions.' },
  { id: 'fieldWork.americanSouth', name: 'American South field-work song', parent: 'fieldWork', description: 'Mississippi Delta field holler, work song, and prison labor song traditions — foundational antecedents to blues.' },
  { id: 'fieldWork.slavicBalkan', name: 'Slavic and Balkan harvest song', parent: 'fieldWork', description: 'Bulgarian zhetvarski, Russian zhnitvenye, Romanian colinde de seceris, Hungarian aratónóta harvest-song traditions.' },
  { id: 'fieldWork.eastAsian', name: 'East Asian field-work song', parent: 'fieldWork', description: 'Chinese chayang diao rice-planting, Korean nongak agricultural drumming, Vietnamese hò boat-and-paddy, Japanese taue uta rice-planting.' },
  { id: 'fieldWork.southAsian', name: 'South Asian field-work song', parent: 'fieldWork', description: 'Bengali bhatiali river-boatmen songs, broader South-Asian agricultural-work-song traditions.' },
  { id: 'fieldWork.subSaharanAfrican', name: 'Sub-Saharan African field-work song', parent: 'fieldWork', description: 'Mande, Wolof, and broader West-African harvest-work-song traditions integrating call-and-response group-vocal practice.' },
  { id: 'fieldWork.andean', name: 'Andean field-work song', parent: 'fieldWork', description: 'Andean Quechua-Aymara huayno-trabajo agricultural-work-song traditions.' },
  { id: 'huntingSong.subSaharanAfrican', name: 'Sub-Saharan African hunting song', parent: 'huntingSong', description: 'BaAka pygmy hunting-polyphony, San-bushman gemsbok-and-eland hunting-song, Yoruba ìrèmọjẹ hunters\'-guild rep.' },
  { id: 'huntingSong.centralAsian', name: 'Central Asian hunting song', parent: 'huntingSong', description: 'Mongolian khoomei hunting-call origin, broader Inner-Asian hunting-song repertoires.' },
  { id: 'huntingSong.arctic', name: 'Arctic and Sami hunting song', parent: 'huntingSong', description: 'Sami luohti and yoik tracking-and-hunting song traditions.' },
  { id: 'huntingSong.indigenous', name: 'Indigenous-Americas and Pacific hunting song', parent: 'huntingSong', description: 'Maori karanga manu bird-calling, Apache and Lakota hunting-medicine songs, Aboriginal-Australian hunting-songlines.' },
  { id: 'domesticRhythm.celticHebridean', name: 'Celtic-Hebridean domestic rhythm song', parent: 'domesticRhythm', description: 'Hebridean Scottish Gaelic waulking songs / òrain luaidh women\'s tweed-fulling traditions and Irish amhráin saothair spinning songs.' },
  { id: 'domesticRhythm.slavicBaltic', name: 'Slavic and Baltic domestic rhythm song', parent: 'domesticRhythm', description: 'Romanian cântece de tors spinning songs, Lithuanian raudai domestic variants, broader Slavic-and-Baltic women\'s-craft-work song repertoires.' },
  { id: 'domesticRhythm.subSaharanAfrican', name: 'Sub-Saharan African domestic rhythm song', parent: 'domesticRhythm', description: 'Wolof, Mande, and broader West-African women\'s grain-grinding rep.' },
  { id: 'domesticRhythm.southAsian', name: 'South Asian domestic rhythm song', parent: 'domesticRhythm', description: 'Bengali jata-gita grinding-stone songs, broader South-Asian women\'s-craft-work song repertoires.' },
  { id: 'domesticRhythm.eastAsianArctic', name: 'East Asian and Arctic domestic rhythm song', parent: 'domesticRhythm', description: 'Korean baengnyŏn ga loom rep, Sami vuolle during domestic work, broader Northeast-Asian-and-Arctic women\'s-craft-work song repertoires.' },
  { id: 'carnivalProcessional.caribbean', name: 'Caribbean carnival processional', parent: 'carnivalProcessional', description: 'Trinidad Carnival road-march and pan-yard rep (calypso, soca), Caribbean junkanoo (Bahamas, Belize), Cape Verdean kavalu fogu Carnaval.' },
  { id: 'carnivalProcessional.brazilian', name: 'Brazilian carnival processional', parent: 'carnivalProcessional', description: 'Brazilian Carnaval samba-school bateria with enredo theme-song.' },
  { id: 'carnivalProcessional.americanSouth', name: 'American South carnival processional', parent: 'carnivalProcessional', description: 'New Orleans Mardi Gras Indians and second-line brass-band processional.' },
  { id: 'carnivalProcessional.european', name: 'European carnival processional', parent: 'carnivalProcessional', description: 'Cologne and Rhineland Karneval, Venice Carnevale, Aalst Carnival Belgium processional traditions.' },
  { id: 'carnivalProcessional.andean', name: 'Andean carnival processional', parent: 'carnivalProcessional', description: 'Bolivian diablada of Oruro, Peruvian Virgen del Carmen and broader Andean festival processionals.' },
  { id: 'carnivalProcessional.eastAsian', name: 'East Asian festival processional', parent: 'carnivalProcessional', description: 'Korean daeboreum lunar-new-year and Japanese matsuri with taiko-and-fue.' },
  { id: 'carnivalProcessional.southAsian', name: 'South Asian festival processional', parent: 'carnivalProcessional', description: 'Indian Diwali and Holi processionals with shehnai and dhol.' },
];
